// Science Quiz Content — Gyaanpravaha — All 9 chapters, 25 marks each

export type QuestionType = 'mcq' | 'single_word' | 'sentence' | 'long_answer'
export interface MCQOption { label: string; text: string }
export interface Question { id: number; type: QuestionType; marks: number; question: string; options?: MCQOption[]; answer: string; reexplanation: string; hint?: string; sectionId?: number }
export interface ChapterQuiz { chapterId: number; title: string; totalMarks: number; questions: Question[] }

const q1: ChapterQuiz = {
  chapterId: 1, title: 'Magnetism', totalMarks: 25,
  questions: [
    { id: 1, type: 'mcq', marks: 1, question: 'Which of the following is a magnetic substance?', options: [{ label: 'A', text: 'Aluminium' }, { label: 'B', text: 'Copper' }, { label: 'C', text: 'Nickel' }, { label: 'D', text: 'Glass' }], answer: 'C', reexplanation: 'Nickel is a magnetic substance — it is attracted by a magnet. The magnetic substances are iron, nickel, cobalt, and their alloys. Aluminium, copper, and glass are all non-magnetic substances and are not attracted by magnets.' },
    { id: 2, type: 'mcq', marks: 1, question: 'What is the directive property of a magnet?', options: [{ label: 'A', text: 'It attracts magnetic substances' }, { label: 'B', text: 'A freely suspended magnet always rests in north-south direction' }, { label: 'C', text: 'Like poles attract each other' }, { label: 'D', text: 'Magnetic poles occur in pairs' }], answer: 'B', reexplanation: 'The directive property of a magnet is the property by which a freely suspended magnet always aligns itself in the north-south direction. The North pole points toward geographical north and South pole toward geographical south. This is the principle behind the magnetic compass.' },
    { id: 3, type: 'mcq', marks: 1, question: 'What is an electromagnet?', options: [{ label: 'A', text: 'A permanent magnet made from steel' }, { label: 'B', text: 'A natural magnet found in the earth' }, { label: 'C', text: 'A temporary magnet made by passing electric current through a coil around a soft iron bar' }, { label: 'D', text: 'A magnet made by the single touch method' }], answer: 'C', reexplanation: 'An electromagnet is a magnet made by using electric current. When a bar of soft iron is placed inside a coil of insulated copper wire and electric current is passed through the coil, the iron bar becomes a magnet. When the current is turned off, the magnetism disappears. So it is a temporary magnet.' },
    { id: 4, type: 'mcq', marks: 1, question: 'Repulsion is the sure test of magnetism. Which poles repel?', options: [{ label: 'A', text: 'N and S poles repel each other' }, { label: 'B', text: 'Like (similar) poles repel each other' }, { label: 'C', text: 'Unlike poles repel each other' }, { label: 'D', text: 'All poles repel each other' }], answer: 'B', reexplanation: 'Like (similar) poles of a magnet repel each other — N-N repels, and S-S repels. Unlike (dissimilar) poles attract each other — N and S attract. Repulsion is the sure test of magnetism because a magnet can attract a non-magnet (iron piece), but repulsion only occurs between two magnets.' },
    { id: 5, type: 'mcq', marks: 1, question: 'Where does a magnet have MAXIMUM magnetic power?', options: [{ label: 'A', text: 'At the centre' }, { label: 'B', text: 'Uniformly throughout' }, { label: 'C', text: 'At the poles (ends)' }, { label: 'D', text: 'At the middle section' }], answer: 'C', reexplanation: 'A magnet has maximum power at its two poles — the North pole and South pole — which are located at the two ends. As you move towards the centre of the magnet, the magnetic power decreases and becomes negligible at the centre.' },
    { id: 6, type: 'single_word', marks: 1, question: 'What is the name of the naturally occurring magnetic rock?', answer: 'Lodestone (Magnetite)', reexplanation: 'The naturally occurring magnetic rock is called Lodestone or Magnetite. According to legend, it was first discovered by a Greek shepherd named Magnes about 4000 years ago in a place called Magnesia in Northern Greece. The word magnet itself comes from either the shepherd\'s name or the place name.', sectionId: 4 },
    { id: 7, type: 'single_word', marks: 1, question: 'What is magnetic induction?', answer: 'The property by which magnetism is induced in a magnetic substance by bringing a magnet near it (without actual contact)', reexplanation: 'Magnetic induction is the process of inducing magnetism in a magnetic substance (like iron) by merely bringing a magnet near it — without any actual contact between them. The iron piece starts behaving as a magnet due to the influence of the magnetic field.', sectionId: 4 },
    { id: 8, type: 'single_word', marks: 1, question: 'What are the two ways to increase the strength of an electromagnet?', answer: 'Increase the number of turns in the coil, OR increase the electric current through the coil', reexplanation: 'The strength of an electromagnet can be increased by: (1) Increasing the number of turns in the coil wound around the iron bar — more turns create a stronger magnetic field, and (2) Increasing the current being passed through the coil — more current = stronger magnetic effect.', sectionId: 4 },
    { id: 9, type: 'single_word', marks: 1, question: 'What is self-demagnetisation?', answer: 'The tendency of magnets to slowly lose their magnetic strength when not in use and left uncared for', reexplanation: 'Magnets have a tendency to lose their magnetic strength slowly when not in use and are not stored properly. This is called self-demagnetisation. To prevent it, bar magnets are stored in pairs with opposite poles adjacent to each other, with a wooden piece between them and soft iron keepers (pieces of soft iron) at opposite poles.', sectionId: 4 },
    { id: 10, type: 'single_word', marks: 1, question: 'Name the scientist known for discoveries in electromagnetism and electrochemistry, associated with this chapter.', answer: 'Michael Faraday', reexplanation: 'Michael Faraday (1791–1867) was an English scientist who contributed to the fields of electromagnetism and electrochemistry. His main discoveries include electromagnetic induction, diamagnetism, and electrolysis. The unit of capacitance (Farad) is named after him. He is considered one of the greatest experimental scientists in history.', sectionId: 4 },
    { id: 11, type: 'sentence', marks: 2, question: 'Use the phrase "directive property" in a sentence explaining how a compass works.', answer: 'A compass works because of the directive property of magnets — a freely suspended magnet always aligns itself in the north-south direction, so the compass needle always points north, helping navigators, sailors, and pilots find their direction.', hint: 'Directive property = a freely suspended magnet always rests in the north-south direction. A compass contains a freely suspended magnetic needle.', reexplanation: 'The directive property of a magnet is the fundamental principle behind the magnetic compass. The compass contains a freely suspended magnetic needle which, due to the directive property, always aligns north-south. This allows travellers to determine direction in any location.', sectionId: 5 },
    { id: 12, type: 'sentence', marks: 2, question: 'Use the word "magnetic field" in a sentence explaining what it is.', answer: 'The magnetic field is the space around a magnet within which its attractive force can be felt — it can be visualised by sprinkling iron filings around a magnet and tapping the surface, as the filings arrange themselves along the invisible field lines.', hint: 'Magnetic field = the space around a magnet where its attraction can be felt. Iron filings show the pattern of the magnetic field.', reexplanation: 'The magnetic field is the region around a magnet where its influence (attraction/repulsion) can be detected. While invisible to the naked eye, it can be visualised using iron filings which align along the field lines when sprinkled around the magnet.', sectionId: 5 },
    { id: 13, type: 'sentence', marks: 2, question: 'Use the word "demagnetise" in a sentence giving three ways it can happen.', answer: 'A magnet can be demagnetised — that is, made to lose its magnetic property — by repeated hammering, by heating it to a very high temperature, or by dropping it on the floor many times.', hint: 'Demagnetisation methods: hammering, heating, dropping, passing strong current, bringing into contact with other magnets repeatedly, handling roughly.', reexplanation: 'Demagnetisation is the loss of magnetic property. Any rough handling — hammering, heating, dropping, passing strong current through it, or bringing it into repeated contact with other magnets — can cause a magnet to lose its magnetism.', sectionId: 5 },
    { id: 14, type: 'sentence', marks: 2, question: 'Use the term "permanent magnet" in a sentence about one of its uses in everyday technology.', answer: 'Permanent magnets made from steel are used in speakers and microphones — the magnet vibrates along with the electrical signal to produce sound, which is why speakers need strong, lasting permanent magnets rather than temporary electromagnets.', hint: 'Permanent magnets = made from steel/special alloys; strong; do not lose magnetism easily. Uses include speakers, microphones, compasses, refrigerators.', reexplanation: 'Permanent magnets are used in devices where long-lasting, reliable magnetic fields are needed without electricity — such as speakers, microphones, compass needles, refrigerator door seals, and ATM card magnetic strips.', sectionId: 5 },
    { id: 15, type: 'sentence', marks: 2, question: 'Use the phrase "magnetic keeper" in a sentence explaining how bar magnets are stored.', answer: 'Bar magnets are stored in pairs with opposite poles facing each other, with a wooden piece between them, and magnetic keepers — pieces of soft iron — placed at the poles to prevent self-demagnetisation.', hint: 'Magnetic keepers = pieces of soft iron placed at opposite poles of bar magnets during storage to preserve magnetism.', reexplanation: 'Magnetic keepers are pieces of soft iron. During storage, bar magnets are placed in pairs with opposite poles adjacent (N facing S), with a wooden piece between them. Keepers are placed at the poles, forming a closed magnetic circuit that prevents self-demagnetisation.', sectionId: 5 },
    { id: 16, type: 'long_answer', marks: 5, question: 'List all six properties of magnets with a brief explanation of each.', answer: '1. A magnet has two poles — Every magnet has a North pole and a South pole at its two ends. All magnetic power is concentrated at the poles and becomes negligible at the centre.\n2. Magnetic poles occur in pairs only — The North and South poles of a magnet cannot be separated. If you split a bar magnet, each piece becomes a complete magnet with both poles.\n3. A magnet always rests in a north-south direction — When freely suspended, a magnet aligns itself north-south. This is the directive property, and it is the basis of the compass.\n4. A magnet attracts magnetic substances — A magnet attracts iron, nickel, cobalt, and their alloys. This is the attractive property.\n5. Like poles repel, unlike poles attract — N-N and S-S repel each other. N-S attract each other. Repulsion is the sure test of magnetism.\n6. Magnetic induction — A magnet can magnetise a nearby magnetic substance without contact. The substance behaves as a magnet due to the influence of the nearby magnetic field.', hint: 'List all 6: (1) two poles, (2) poles in pairs only, (3) north-south direction (directive property), (4) attracts magnetic substances (attractive property), (5) like repel, unlike attract, (6) magnetic induction.', reexplanation: 'Cover all six properties in order: two poles (N and S, all power at poles); poles in pairs (cannot separate N and S); directive property (always N-S when freely suspended, basis of compass); attractive property (attracts iron, nickel, cobalt); like repel unlike attract (repulsion is sure test); magnetic induction (magnetises nearby substance without contact).', sectionId: 7 },
  ],
}

const q2: ChapterQuiz = {
  chapterId: 2, title: 'Simple Machines', totalMarks: 25,
  questions: [
    { id: 1, type: 'mcq', marks: 1, question: 'In a first order lever, where is the fulcrum?', options: [{ label: 'A', text: 'Between load and effort' }, { label: 'B', text: 'Between fulcrum and effort' }, { label: 'C', text: 'At the end of the lever' }, { label: 'D', text: 'Between load and fulcrum' }], answer: 'A', reexplanation: 'In a first order lever, the fulcrum is between the load and the effort. The classic example is a seesaw — the pivot (fulcrum) is in the middle, with people (load and effort) on either side. Other examples: scissors, pliers, tin opener.' },
    { id: 2, type: 'mcq', marks: 1, question: 'A wheelbarrow is an example of which order of lever?', options: [{ label: 'A', text: 'First order' }, { label: 'B', text: 'Second order' }, { label: 'C', text: 'Third order' }, { label: 'D', text: 'Fourth order' }], answer: 'B', reexplanation: 'A wheelbarrow is a second order lever. In second order levers, the load is between the fulcrum and the effort. The wheel is the fulcrum (at the front), the load is in the middle (the container), and the effort is applied at the handles (at the back). Effort arm is always bigger than load arm in second order levers.' },
    { id: 3, type: 'mcq', marks: 1, question: 'The formula for Mechanical Advantage is:', options: [{ label: 'A', text: 'MA = Effort × Load' }, { label: 'B', text: 'MA = Load / Effort' }, { label: 'C', text: 'MA = Effort / Load' }, { label: 'D', text: 'MA = Load + Effort' }], answer: 'B', reexplanation: 'Mechanical Advantage = Load (W) / Effort (E) = Effort arm / Load arm. MA is a ratio with no units. If MA = 3, the machine multiplies your effort 3 times, meaning you apply 1 unit of force to overcome 3 units of load.' },
    { id: 4, type: 'mcq', marks: 1, question: 'What is a screw?', options: [{ label: 'A', text: 'A simple pulley system' }, { label: 'B', text: 'A modified inclined plane (winding inclined plane)' }, { label: 'C', text: 'A type of wheel and axle' }, { label: 'D', text: 'A first order lever' }], answer: 'B', reexplanation: 'A screw is a modified inclined plane — a winding inclined plane. It consists of a nail with a winding edge called a thread. The distance between two successive threads is called the pitch. When one rotation is given to the screw, it moves a vertical distance equal to the pitch. This is why it is easier to drive a screw with a screwdriver than to hammer it.' },
    { id: 5, type: 'mcq', marks: 1, question: 'A load of 200 N is lifted with an effort of 50 N. What is the Mechanical Advantage?', options: [{ label: 'A', text: '1' }, { label: 'B', text: '2' }, { label: 'C', text: '4' }, { label: 'D', text: '10000' }], answer: 'C', reexplanation: 'MA = Load / Effort = 200 N / 50 N = 4. The machine multiplies the effort 4 times, meaning you apply 50 N of effort to overcome a 200 N load. MA has no units (it is a pure ratio).' },
    { id: 6, type: 'single_word', marks: 1, question: 'What is the fixed point about which a lever turns?', answer: 'Fulcrum', reexplanation: 'The fulcrum is the fixed point about which a lever turns (pivots). In a seesaw, the central support is the fulcrum. In a pair of scissors, the rivet/screw connecting the two blades is the fulcrum. The fulcrum determines the type of lever (first, second, or third order) based on its position relative to load and effort.', sectionId: 4 },
    { id: 7, type: 'single_word', marks: 1, question: 'Name two examples of third order levers.', answer: 'Forearm/human arm AND sugar tongs / forceps / knife', reexplanation: 'In a third order lever, effort is between load and fulcrum. The effort arm is always smaller than the load arm. Third order levers are used for delicate tasks requiring precision rather than force multiplication. Examples: human forearm (elbow = fulcrum, biceps = effort, hand = load), sugar tongs, forceps, knife.', sectionId: 4 },
    { id: 8, type: 'single_word', marks: 1, question: 'What is the main advantage of wheel and axle as a machine?', answer: 'It reduces friction because rolling friction is less than sliding friction', reexplanation: 'The wheel is the most important invention of mankind. The wheel rotates along a central rod called the axle. The main advantage is that it reduces friction — rolling friction (when a wheel rolls) is significantly less than sliding friction (when a surface slides against another surface). This is why all vehicles use wheels.', sectionId: 4 },
    { id: 9, type: 'single_word', marks: 1, question: 'Why are mountain roads made winding (not straight)?', answer: 'To make the slope gradual (inclined plane), which multiplies the distance but reduces the force needed for vehicles to climb', reexplanation: 'A winding mountain road is an application of the inclined plane principle. The rule is: the lesser the inclination of the plane, the less force is needed to climb it. By making the road wind around the mountain in a zigzag (gradual slope), the effective angle of climb is reduced and vehicles can climb with much less effort than if the road went straight up.', sectionId: 4 },
    { id: 10, type: 'single_word', marks: 1, question: 'State the principle of lever as a formula.', answer: 'Effort × Effort Arm = Load × Load Arm (or MA = Effort Arm / Load Arm)', reexplanation: 'The principle of lever states: Effort × Effort Arm = Load × Load Arm. This means a small effort applied over a large effort arm can balance or overcome a large load applied over a small load arm. From this principle, MA = Effort Arm / Load Arm = Load / Effort.', sectionId: 4 },
    { id: 11, type: 'sentence', marks: 2, question: 'Use the word "fulcrum" in a sentence explaining how a seesaw works as a first order lever.', answer: 'A seesaw is a first order lever where the fulcrum — the pivot at the centre — is between the two children (load and effort), and by adjusting the position of the fulcrum, a lighter child can balance a heavier one.', hint: 'Seesaw: first order lever, fulcrum is in the middle between load and effort. Longer effort arm = less effort needed to overcome the same load.', reexplanation: 'A seesaw demonstrates the first order lever perfectly. The fulcrum is in the middle. If one child is heavier, the lighter child can balance them by moving further from the fulcrum (increasing the effort arm). MA = effort arm / load arm. If effort arm > load arm, MA > 1 and lighter effort can overcome heavier load.', sectionId: 5 },
    { id: 12, type: 'sentence', marks: 2, question: 'Use the word "pulley" in a sentence explaining how it makes lifting easier.', answer: 'A pulley makes lifting easier by changing the direction of the applied force — instead of lifting a bucket upward against gravity, you pull the rope downward in the direction of gravity, which is a more convenient and less tiring direction of force.', hint: 'Pulley: changes direction of applied force. Pulling down (direction of gravity) is easier than pulling up (against gravity).', reexplanation: 'A pulley is a simple machine that changes the direction of the applied force. Drawing water from a well is the classic example — without a pulley, you must pull the bucket upward against gravity (very tiring). With a pulley, you pull the rope downward (in the direction of gravity), which requires the same force but feels easier and is more convenient.', sectionId: 5 },
    { id: 13, type: 'sentence', marks: 2, question: 'Use the phrase "mechanical advantage" in a sentence to explain why machines are useful.', answer: 'Machines are useful because they provide mechanical advantage — a ratio of load to effort greater than 1 means a small effort can overcome a much larger load, like using a screw jack to lift a car with very little force.', hint: 'MA = Load/Effort. MA > 1 means machine multiplies effort. MA = 4 means 1 unit of effort overcomes 4 units of load.', reexplanation: 'Mechanical advantage is the reason machines make work easier. When MA > 1, the machine multiplies the effort applied — you apply less force to overcome a greater load. A screw jack with MA of 100 means you apply 1 unit of force to lift 100 units of load — this is why a person can lift a car with a screw jack.', sectionId: 5 },
    { id: 14, type: 'sentence', marks: 2, question: 'Use the word "wedge" in a sentence with two examples.', answer: 'A wedge is a simple machine with two or more sloping surfaces that taper to a sharp edge — a knife used to cut vegetables and an axe used to chop wood are both examples of wedges.', hint: 'Wedge = two sloping surfaces tapering to a sharp edge or point. Examples: knife, chisel, axe, pin, needle, nail.', reexplanation: 'A wedge converts a force applied to its blunt end into forces perpendicular to its inclined surfaces — splitting or piercing the material. Common examples include knives (for cutting), chisels (for carving wood/stone), axes (for chopping), pins and needles (for piercing), and nails (for joining materials).', sectionId: 5 },
    { id: 15, type: 'sentence', marks: 2, question: 'Use the phrase "maintenance of machines" in a sentence listing three ways to care for machines.', answer: 'Regular maintenance of machines involves cleaning them regularly, oiling the moving parts to reduce friction and wear, and preventing iron parts from rusting through painting — all of which extend the machine\'s life and efficiency.', hint: 'Machine maintenance: clean regularly, oil moving parts (reduces friction, noise, wear), prevent rusting (paint iron parts), adjust moving parts as needed.', reexplanation: 'Machines require regular maintenance because they have moving parts that are subject to rusting, friction, and dirt accumulation. Regular cleaning removes dirt, regular oiling reduces friction (and thereby reduces noise, wear and heat), and painting or other treatments prevent iron parts from rusting.', sectionId: 5 },
    { id: 16, type: 'long_answer', marks: 5, question: 'Describe all six types of simple machines with one example of each and explain what makes each one a useful machine.', answer: '1. Lever: A rigid bar turning about a fulcrum. Example: seesaw (first order lever). Useful because it can multiply force (large effort arm overcomes large load with small effort). 2. Pulley: A wheel with a groove and rope that changes direction of force. Example: well with rope and pulley. Useful because pulling down (direction of gravity) is more convenient than lifting up. 3. Inclined Plane: A sloped surface. Example: road winding up a mountain. Useful because a gentle slope requires less force to move a heavy load upward. 4. Screw: A modified inclined plane with threads. Example: bolt and screw. Useful because rotation converts to linear movement, providing strong grip — difficult to pull out once driven in. 5. Wedge: Two sloping surfaces tapering to an edge. Example: knife. Useful because it converts a downward force into sideways forces, splitting or piercing materials. 6. Wheel and Axle: A wheel rotating around a central rod. Example: bicycle wheel. Useful because rolling friction is less than sliding friction, greatly reducing the effort needed to move loads.', hint: 'Name all 6: lever (fulcrum), pulley (changes direction), inclined plane (gentle slope), screw (winding inclined plane), wedge (tapering surfaces), wheel and axle (rolling friction). Give one example and one benefit for each.', reexplanation: 'All 6 types: Lever (fulcrum, load, effort — seesaw, scissors), Pulley (changes direction — well pulley, flagpole), Inclined plane (gentle slope — mountain road, loading ramp), Screw (winding inclined plane, thread, pitch — bolts, screwdrivers), Wedge (two sloping surfaces — knife, axe, nail), Wheel and axle (rolling < sliding friction — bicycle, vehicles, trolleys).', sectionId: 7 },
  ],
}

const q3: ChapterQuiz = {
  chapterId: 3, title: 'Work and Energy', totalMarks: 25,
  questions: [
    { id: 1, type: 'mcq', marks: 1, question: 'A boy pushes a heavy stone with all his strength but the stone does not move. How much work has he done?', options: [{ label: 'A', text: 'A lot of work' }, { label: 'B', text: 'Zero work' }, { label: 'C', text: 'Some work' }, { label: 'D', text: 'Cannot be determined' }], answer: 'B', reexplanation: 'The boy has done zero work. In Physics, work is done ONLY when a force produces motion. The two conditions for work: (1) a force must act on the body, AND (2) the force must produce motion. If the stone does not move, no motion is produced, so no work is done — regardless of how hard he pushes or how tired he gets.' },
    { id: 2, type: 'mcq', marks: 1, question: 'What is the SI unit of work?', options: [{ label: 'A', text: 'Newton' }, { label: 'B', text: 'Metre' }, { label: 'C', text: 'Joule' }, { label: 'D', text: 'Watt' }], answer: 'C', reexplanation: 'The SI unit of work (and energy) is the Joule (J), named after James Prescott Joule. 1 Joule = 1 Newton × 1 Metre = 1 N.m. The newton is the unit of force, the metre is the unit of distance, and the watt is the unit of power (rate of doing work).' },
    { id: 3, type: 'mcq', marks: 1, question: 'Which of the following is an example of potential energy?', options: [{ label: 'A', text: 'A rolling ball' }, { label: 'B', text: 'A moving car' }, { label: 'C', text: 'Water stored at a height in a dam' }, { label: 'D', text: 'A fired bullet' }], answer: 'C', reexplanation: 'Water stored at a height in a dam has potential energy — energy possessed due to its position (height). All the other options (rolling ball, moving car, fired bullet) have kinetic energy — energy possessed by virtue of motion.' },
    { id: 4, type: 'mcq', marks: 1, question: 'Which is a renewable source of energy?', options: [{ label: 'A', text: 'Coal' }, { label: 'B', text: 'Petrol' }, { label: 'C', text: 'Natural gas' }, { label: 'D', text: 'Wind' }], answer: 'D', reexplanation: 'Wind is a renewable source of energy — it can be used again and again and will never run out. Wind is freely available, does not pollute the environment, and is inexhaustible. Coal, petrol, and natural gas are all non-renewable — once used, they cannot be replaced, and they took millions of years to form.' },
    { id: 5, type: 'mcq', marks: 1, question: 'State the Law of Conservation of Energy:', options: [{ label: 'A', text: 'Energy can be created by machines' }, { label: 'B', text: 'Energy can be destroyed if sufficient heat is applied' }, { label: 'C', text: 'Energy can neither be created nor destroyed, only changed from one form to another' }, { label: 'D', text: 'Total energy in the universe decreases over time' }], answer: 'C', reexplanation: 'The Law of Conservation of Energy states: Energy can neither be created nor destroyed. It can only be changed from one form to another. The total amount of energy in the universe always remains constant. This is one of the most fundamental laws of science.' },
    { id: 6, type: 'single_word', marks: 1, question: 'State the formula for work done.', answer: 'W = F × d (Work = Force × Distance moved in the direction of force)', reexplanation: 'Work = Force × Distance moved in the direction of force. W = F × d. Force is measured in Newtons (N), distance in metres (m), and work in Joules (J). If a force of 10 N moves an object 5 m, work done = 10 × 5 = 50 J.', sectionId: 4 },
    { id: 7, type: 'single_word', marks: 1, question: 'A force of 100 N moves a body through 3 m. Calculate the work done.', answer: '300 J (W = 100 N × 3 m = 300 J)', reexplanation: 'Using W = F × d: W = 100 N × 3 m = 300 N.m = 300 Joules. The SI unit of work is the Joule (J) = Newton × metre (N.m). Named after James Prescott Joule.', sectionId: 4 },
    { id: 8, type: 'single_word', marks: 1, question: 'What is the capacity of a body to do work called?', answer: 'Energy', reexplanation: 'Energy is defined as the capacity (ability) to do work. A body that has energy can do work. Energy and work are measured in the same SI unit — the Joule (J). You cannot do work without energy, and energy is always used or transformed when work is done.', sectionId: 4 },
    { id: 9, type: 'single_word', marks: 1, question: 'What is biogas and what is it made of?', answer: 'Biogas is a mixture of Methane and Carbon dioxide, produced from the decomposition of biomass (biological matter) in the absence of oxygen', reexplanation: 'Biogas is a mixture of methane (CH₄) and carbon dioxide (CO₂). It is produced when biomass — cow dung, sewage, garbage, crop residue — decomposes in the absence of oxygen. Biogas is a non-polluting fuel that can be burned to produce heat and electricity. It is a renewable source of energy.', sectionId: 4 },
    { id: 10, type: 'single_word', marks: 1, question: 'Name the scientist after whom the SI unit of energy is named.', answer: 'James Prescott Joule', reexplanation: 'James Prescott Joule (1818–1889) was an English physicist who studied the nature of heat and discovered its relationship to mechanical work. His work led to the theory of conservation of energy and the first law of thermodynamics. The SI unit of energy — the joule (J) — is named after him.', sectionId: 4 },
    { id: 11, type: 'sentence', marks: 2, question: 'Use the phrase "potential energy" in a sentence about a stretched rubber band.', answer: 'A stretched rubber band stores potential energy due to its changed shape, and when released, this potential energy is converted into kinetic energy which snaps the band back to its original shape.', hint: 'Potential energy: energy due to position or change in shape. Stretched rubber band has PE due to its stretched (changed) shape. When released, PE converts to KE.', reexplanation: 'A stretched rubber band is a classic example of elastic potential energy — energy stored in an object due to its deformation (change in shape). When the rubber band is released, the stored PE is converted to KE as the band snaps back. This conversion of PE to KE is what gives the rubber catapult its power.', sectionId: 5 },
    { id: 12, type: 'sentence', marks: 2, question: 'Use the phrase "conservation of energy" in a sentence with a practical example.', answer: 'Conservation of energy in daily life means using energy wisely — switching off lights and fans when leaving a room prevents waste of electrical energy, which ultimately comes from limited non-renewable sources like coal.', hint: 'Conservation of energy = economic use of energy. Examples: switching off appliances, using pressure cooker, driving only when necessary, not wasting water.', reexplanation: 'Conservation of energy as a practical concept means using available energy responsibly to avoid waste. Electrical energy used to power a fan comes ultimately from burning coal or other fuels. Switching off the fan when not needed saves that energy for future use and reduces pollution.', sectionId: 5 },
    { id: 13, type: 'sentence', marks: 2, question: 'Use the words "kinetic energy" in a sentence giving two factors it depends on.', answer: 'Kinetic energy depends on two factors: the mass of the body (greater mass = higher kinetic energy) and the speed of the body (more speed = higher kinetic energy), which is why a heavy truck moving fast has far more kinetic energy than a small ball rolling slowly.', hint: 'KE depends on: (1) mass of body (greater mass → more KE) and (2) speed of body (more speed → more KE).', reexplanation: 'Kinetic energy depends on mass and speed. A heavier object moving at the same speed has more kinetic energy than a lighter object (which is why a truck causes more damage in a collision than a bicycle). A faster object also has more kinetic energy than a slower object of the same mass.', sectionId: 5 },
    { id: 14, type: 'sentence', marks: 2, question: 'Use the phrase "renewable energy" in a sentence with three examples and why they are better than coal.', answer: 'Renewable energy sources like the sun, wind, and flowing water are better than coal because they can be used again and again without running out, they are freely available, and they do not pollute the environment as fossil fuels do.', hint: 'Renewable energy: sun, wind, water, biomass — can be used again and again, never run out, freely available, non-polluting. Non-renewable (coal, petrol) = run out, costly, polluting.', reexplanation: 'Renewable energy sources are superior to coal (non-renewable) in three key ways: (1) they will never run out (sun will shine, wind will blow for billions of years), (2) they are available at little or no cost, and (3) they do not produce greenhouse gases or pollution when used.', sectionId: 5 },
    { id: 15, type: 'sentence', marks: 2, question: 'Use the word "joule" in a sentence solving this problem: A force of 50 N moves a box 4 m. Calculate work done.', answer: 'Using W = F × d, the work done by the force is 50 N × 4 m = 200 joules (J) — showing that the amount of work depends on both the magnitude of force and the distance the box moves.', hint: 'W = F × d = 50 × 4 = 200 J. Joule is the SI unit of work = N × m.', reexplanation: 'W = F × d = 50 N × 4 m = 200 N.m = 200 J. One joule is defined as the work done when a force of 1 Newton moves an object through 1 metre in the direction of the force. The joule is named after the English physicist James Prescott Joule.', sectionId: 5 },
    { id: 16, type: 'long_answer', marks: 5, question: 'Name and describe all 8 forms of energy, giving one example of each.', answer: '1. Mechanical energy — Energy due to position, shape, or motion. Examples: a moving car (kinetic), water at height in a dam (potential).\n2. Heat energy — Released when fuel is burned. Example: heat energy from burning coal warms a room; steam from a kettle moves the lid.\n3. Light energy — A form of energy that helps us see. Example: the tail of a comet is pushed away from the sun by light energy.\n4. Chemical energy — Stored in fuels and food. Example: petrol has chemical energy that powers a car; food gives us chemical energy to work.\n5. Sound energy — Possessed by a vibrating body. Example: a speaker vibrates to produce sound energy from electrical energy.\n6. Magnetic energy — Possessed by a magnet. Example: a magnet attracts an iron nail from a distance, moving it — doing work using magnetic energy.\n7. Electrical energy — Produced when dry bodies are rubbed together or by generators. Example: electric current in a wire powers a fan.\n8. Atomic energy — Stored in atoms. Example: nuclear reactors use atomic energy to produce electricity (peaceful use).', hint: 'List all 8: Mechanical (KE + PE), Heat, Light, Chemical, Sound, Magnetic, Electrical, Atomic. One example for each.', reexplanation: 'All 8 forms: (1) Mechanical (moving car, water at height), (2) Heat (burning coal, steam), (3) Light (comet\'s tail, solar panels), (4) Chemical (petrol, food, batteries), (5) Sound (speaker, vibrating bell), (6) Magnetic (magnet attracts nail, electric motor), (7) Electrical (electric current, static electricity), (8) Atomic (nuclear reactor, atom bomb).', sectionId: 7 },
  ],
}

const q4: ChapterQuiz = {
  chapterId: 4, title: 'Introduction to Chemistry', totalMarks: 25,
  questions: [
    { id: 1, type: 'mcq', marks: 1, question: 'Who is called the father of modern chemistry?', options: [{ label: 'A', text: 'John Dalton' }, { label: 'B', text: 'Jons Berzelius' }, { label: 'C', text: 'Antoine Lavoisier' }, { label: 'D', text: 'Ernest Rutherford' }], answer: 'C', reexplanation: 'Antoine Lavoisier (1743–1794), a French scientist, is called the father of modern chemistry. He established the law of conservation of mass and explained the role of oxygen in combustion. John Dalton gave the atomic theory, Jons Berzelius gave element symbols, and Ernest Rutherford discovered the atomic nucleus.' },
    { id: 2, type: 'mcq', marks: 1, question: 'What is chemistry?', options: [{ label: 'A', text: 'Study of living organisms' }, { label: 'B', text: 'Study of substances, their nature, properties, and how they react' }, { label: 'C', text: 'Study of forces and energy' }, { label: 'D', text: 'Study of stars and planets' }], answer: 'B', reexplanation: 'Chemistry is a branch of science that deals with the study of different kinds of substances, their nature and properties, and how they react with each other. A person who studies and specialises in chemistry is called a chemist.' },
    { id: 3, type: 'mcq', marks: 1, question: 'Which ancient Indian city used metals like copper, lead, tin, and bronze around 2500 B.C.?', options: [{ label: 'A', text: 'Mathura' }, { label: 'B', text: 'Harappa' }, { label: 'C', text: 'Varanasi' }, { label: 'D', text: 'Pataliputra' }], answer: 'B', reexplanation: 'People in Harappa in ancient India (about 2500 B.C.) used metals like copper, lead, and tin, and alloys like bronze. They made fire-baked bricks and clay pots. About 3000 years ago, iron was extracted in India — showing that chemical processes were part of Indian civilisation thousands of years ago.' },
    { id: 4, type: 'mcq', marks: 1, question: 'Nylon, rayon, and terylene are:', options: [{ label: 'A', text: 'Natural fibres' }, { label: 'B', text: 'Minerals' }, { label: 'C', text: 'Synthetic fibres — gifts of chemistry' }, { label: 'D', text: 'Types of metals' }], answer: 'C', reexplanation: 'Nylon, rayon, terylene, and flame-proof textiles are synthetic fibres — they are manufactured through chemical processes and are gifts of chemistry. Natural fibres (cotton, wool, silk) come from plants and animals, but synthetic fibres are entirely man-made through chemical reactions.' },
    { id: 5, type: 'mcq', marks: 1, question: 'John Dalton (1766–1844) is famous for:', options: [{ label: 'A', text: 'Discovering penicillin' }, { label: 'B', text: 'Giving the atomic theory' }, { label: 'C', text: 'Creating the modern symbols of elements' }, { label: 'D', text: 'Pasteurisation' }], answer: 'B', reexplanation: 'John Dalton (1766–1844), an English chemist, is famous for giving the atomic theory — that all matter is made of atoms, which are the smallest particles of an element that can take part in a chemical reaction. Jons Berzelius created element symbols, and Alexander Fleming discovered penicillin.' },
    { id: 6, type: 'single_word', marks: 1, question: 'What is a person who studies chemistry called?', answer: 'A chemist', reexplanation: 'A person who studies and gains specialisation in chemistry is called a chemist. Chemists work in many fields including pharmaceuticals (medicines), materials science, food processing, cosmetics, agriculture, and industrial manufacturing.', sectionId: 4 },
    { id: 7, type: 'single_word', marks: 1, question: 'Name three branches of modern chemistry.', answer: 'Any three from: Inorganic chemistry, Organic chemistry, Physical chemistry, Analytical chemistry, Biochemistry, Nuclear chemistry', reexplanation: 'Modern chemistry has developed many specialised branches: Inorganic chemistry (non-carbon compounds), Organic chemistry (carbon compounds), Physical chemistry (energy and rates of reactions), Analytical chemistry (identifying substances), Biochemistry (chemistry of living organisms), Nuclear chemistry (radioactivity and nuclear reactions).', sectionId: 4 },
    { id: 8, type: 'single_word', marks: 1, question: 'Name three ways chemistry has helped agriculture.', answer: 'Production of artificial fertilisers, better seeds, insecticides/pesticides/fungicides/herbicides', reexplanation: 'Chemistry has helped agriculture in three main ways: (1) Production of artificial fertilisers which increase food production by adding nutrients to soil; (2) Development of better seeds through chemical treatment; (3) Production of insecticides, pesticides, fungicides, and herbicides to protect crops from pests, insects, fungi, and weeds.', sectionId: 4 },
    { id: 9, type: 'single_word', marks: 1, question: 'What did ancient scientists believe everything was made of (before modern chemistry)?', answer: 'Four elements: air, water, fire, and earth (some added space as a fifth element)', reexplanation: 'Until the middle of the 17th century, most people and even scientists believed that everything in the world was made of four elements: air, water, fire, and earth. Some people considered space as the fifth element. Modern chemistry, beginning with Lavoisier, proved this wrong by demonstrating that these are not elements but mixtures and compounds of actual elements.', sectionId: 4 },
    { id: 10, type: 'single_word', marks: 1, question: 'Who gave the modern symbols of elements (like H for hydrogen, O for oxygen)?', answer: 'Jons Berzelius (1779–1884), a Swedish chemist', reexplanation: 'Jons Berzelius (1779–1884), a Swedish chemist, created the modern system of element symbols that we still use today. He used letters from the Latin or English names of elements — H for Hydrogen, O for Oxygen, Fe for Iron (Ferrum in Latin), Na for Sodium (Natrium in Latin). His system is universally used in chemistry worldwide.', sectionId: 4 },
    { id: 11, type: 'sentence', marks: 2, question: 'Use the word "chemist" in a sentence about one specific contribution of chemistry to medicine.', answer: 'Chemists have developed life-saving drugs through chemical reactions — antibiotics, painkillers, vaccines, and cancer treatments have all been manufactured as a result of intensive chemical research, enabling people to live healthier and longer lives.', hint: 'Chemistry and medicines: various medicines are manufactured as result of chemical reactions. These life-saving drugs enable healthier, longer lives.', reexplanation: 'Chemistry has transformed medicine. Almost every medicine you take — from a paracetamol tablet to a cancer drug — is the product of chemical research and manufacturing processes. Chemists design molecules that interact with specific biological targets in the human body to treat diseases.', sectionId: 5 },
    { id: 12, type: 'sentence', marks: 2, question: 'Use the word "fertiliser" in a sentence explaining how chemistry has helped food production.', answer: 'Artificial fertilisers developed through chemistry replenish essential nutrients like nitrogen, phosphorus, and potassium in the soil, dramatically increasing crop yields and enabling modern agriculture to feed the world\'s large population.', hint: 'Chemistry helped agriculture through: artificial fertilisers (increase food production), better seeds, insecticides, pesticides, fungicides, herbicides.', reexplanation: 'Artificial fertilisers are manufactured through chemical processes — for example, the Haber process converts atmospheric nitrogen to ammonia, which is used to make nitrogen-based fertilisers. These fertilisers have dramatically increased agricultural yields globally.', sectionId: 5 },
    { id: 13, type: 'sentence', marks: 2, question: 'Use the phrase "ancient Indian chemistry" in a sentence about Harappan civilisation.', answer: 'Ancient Indian chemistry was already highly developed in the Harappan civilisation around 2500 B.C., where people extracted and worked with metals like copper, lead, and tin, made bronze alloys, fired bricks in kilns, and moulded clay pots — all chemical processes.', hint: 'Harappa (2500 B.C.): used copper, lead, tin, bronze. Made fire-baked bricks, clay pots. Iron extracted in India ~3000 years ago.', reexplanation: 'The Harappan civilisation demonstrates India\'s ancient chemical knowledge. Extracting metals from ores (smelting), making alloys (bronze = copper + tin), firing bricks (which converts clay into a hard ceramic material through chemical change), and working with clay are all chemical processes — showing sophisticated understanding of materials.', sectionId: 5 },
    { id: 14, type: 'sentence', marks: 2, question: 'Use the word "bleaching" in a sentence about chemistry\'s role in the textile industry.', answer: 'Bleaching — a chemical process that removes colour from fabric — allows natural fibres like cotton and linen to be lightened before dyeing, giving chemists and manufacturers control over the final colour and appearance of clothing.', hint: 'Chemistry and clothing: natural fibres (cotton, wool, silk) given better look through chemical processes like dyeing and bleaching. Synthetic fibres (nylon, rayon) are gifts of chemistry.', reexplanation: 'Bleaching is a chemical process that oxidises or reduces the colour compounds in fabric. It can lighten fabric to white (using chlorine bleach or hydrogen peroxide) or produce specific effects. Chemistry gives us both the ability to remove colour (bleaching) and add new colour (dyeing) to fabrics.', sectionId: 5 },
    { id: 15, type: 'sentence', marks: 2, question: 'Use the phrase "nuclear chemistry" in a sentence about its two uses.', answer: 'Nuclear chemistry deals with radioactivity and nuclear reactions — it has two major applications: peaceful use in nuclear reactors to generate electricity, and destructive use in nuclear weapons.', hint: 'Atomic/nuclear energy: peaceful use = nuclear reactors produce electricity. Destructive use = atomic bombs used in war.', reexplanation: 'Nuclear chemistry deals with nuclear reactions, radioactive decay, and nuclear energy. Its peaceful use involves nuclear power plants where controlled nuclear fission reactions generate enormous amounts of electricity. Its destructive use — in nuclear weapons — releases the same energy in an uncontrolled explosion.', sectionId: 5 },
    { id: 16, type: 'long_answer', marks: 5, question: 'Explain how chemistry helps in four areas of daily life: food, clothing, medicines, and cosmetics. Give at least two examples for each area.', answer: 'Chemistry impacts daily life in four major areas. In food and agriculture: chemistry has developed artificial fertilisers that increase crop yields, and pesticides, insecticides and herbicides that protect crops; many food items like curd, butter, cheese, ghee, refined oil, baby food, and beverages are made through chemical processes. In clothing: chemistry has enabled better natural fibre treatment through dyeing and bleaching; it has also created entirely new materials — synthetic fibres like nylon, rayon, terylene, and flame-proof textiles that would not exist without chemical research. In medicines: virtually all medicines prescribed by doctors are manufactured through chemical reactions — antibiotics, painkillers, vaccines, and life-saving drugs have enabled people to live healthier and longer lives. In cosmetics: all powders, creams, nail polishes, lipsticks, cleansing lotions, soaps, and detergents are the result of research by chemists — these products improve hygiene and personal care for millions of people.', hint: 'Cover all 4 areas: (1) Food: fertilisers, pesticides, food processing (curd, butter, cheese, ghee); (2) Clothing: dyeing, bleaching, synthetic fibres (nylon, rayon, terylene); (3) Medicines: life-saving drugs from chemical reactions; (4) Cosmetics: powders, creams, soaps, detergents.', reexplanation: 'Food (fertilisers + better seeds + pesticides/insecticides + food processing), Clothing (dyeing + bleaching of natural fibres + synthetic fibres: nylon, rayon, terylene, flame-proof textiles), Medicines (all prescription drugs manufactured through chemical reactions, enabling healthier longer lives), Cosmetics (all personal care products — powders, creams, nail polish, lipstick, soaps, detergents — result from chemical research).', sectionId: 7 },
  ],
}

const q5: ChapterQuiz = {
  chapterId: 5, title: 'Structure of Atom', totalMarks: 25,
  questions: [
    { id: 1, type: 'mcq', marks: 1, question: 'What is the atomic number of an element?', options: [{ label: 'A', text: 'Number of neutrons in the nucleus' }, { label: 'B', text: 'Number of protons in the nucleus' }, { label: 'C', text: 'Total number of protons and neutrons' }, { label: 'D', text: 'Number of electrons in the outer shell' }], answer: 'B', reexplanation: 'Atomic number (Z) = Number of protons in the nucleus. Since an atom is neutral (no overall charge), the number of protons equals the number of electrons. So Z = p = e. The atomic number uniquely identifies the element — change the atomic number and you have a different element.' },
    { id: 2, type: 'mcq', marks: 1, question: 'The maximum number of electrons in the L shell (second shell, n=2) is:', options: [{ label: 'A', text: '2' }, { label: 'B', text: '8' }, { label: 'C', text: '18' }, { label: 'D', text: '32' }], answer: 'B', reexplanation: 'Maximum electrons in each shell = 2n² (where n is the shell number). For L shell: n = 2, so maximum = 2 × 2² = 2 × 4 = 8 electrons. K shell (n=1): max 2. L shell (n=2): max 8. M shell (n=3): max 18.' },
    { id: 3, type: 'mcq', marks: 1, question: 'What is the charge of a neutron?', options: [{ label: 'A', text: '+1' }, { label: 'B', text: '-1' }, { label: 'C', text: '0 (no charge)' }, { label: 'D', text: '+2' }], answer: 'C', reexplanation: 'A neutron has no charge (charge = 0) and a unit mass of 1 atomic mass unit. It is located in the nucleus along with protons. The proton has +1 charge and mass 1. The electron has -1 charge and negligible mass (approximately 0).' },
    { id: 4, type: 'mcq', marks: 1, question: 'The mass number of an atom is 35 and atomic number is 17. How many neutrons does it have?', options: [{ label: 'A', text: '35' }, { label: 'B', text: '17' }, { label: 'C', text: '18' }, { label: 'D', text: '52' }], answer: 'C', reexplanation: 'Neutrons = Mass number (A) − Atomic number (Z) = 35 − 17 = 18 neutrons. This is the element Chlorine (Cl). It has 17 protons, 17 electrons, and 18 neutrons.' },
    { id: 5, type: 'mcq', marks: 1, question: 'Who was the first to suggest that all matter is made of tiny indivisible particles (parmanu)?', options: [{ label: 'A', text: 'Neil Bohr' }, { label: 'B', text: 'Ernest Rutherford' }, { label: 'C', text: 'Indian sage Kanada' }, { label: 'D', text: 'John Dalton' }], answer: 'C', reexplanation: 'The great Indian sage Kanada (around 600 B.C.) was perhaps the first to suggest that all matter, irrespective of its physical state, is composed of very small particles called parmanu or anu. This ancient Indian concept preceded the modern Western atomic theory by over 2000 years.' },
    { id: 6, type: 'single_word', marks: 1, question: 'State the formula for mass number.', answer: 'A = n + p (Mass number = neutrons + protons)', reexplanation: 'Mass number (A) = number of neutrons (n) + number of protons (p). A = n + p. Since atomic number Z = p, we can write: n = A − Z (neutrons = mass number − atomic number). The mass number gives the total number of particles in the nucleus (protons + neutrons).', sectionId: 4 },
    { id: 7, type: 'single_word', marks: 1, question: 'Find the electronic configuration of Sodium (Na): Z=11, A=23.', answer: 'K=2, L=8, M=1 (Neutrons = 23−11 = 12)', reexplanation: 'Sodium has Z=11, so 11 electrons. Fill shells in order: K=2, L=8, M=1 (2+8+1=11). The K shell is filled first (max 2), then L shell (max 8), and the remaining 1 electron goes into M shell. Neutrons = A−Z = 23−11 = 12.', sectionId: 4 },
    { id: 8, type: 'single_word', marks: 1, question: 'Name the subatomic particle that is involved in protein synthesis (found in ribosomes).', answer: 'This is about ribosomes (organelles) — but in atomic structure: electrons are the subatomic particles that determine chemical reactions and bonding between atoms', reexplanation: 'Electrons are the subatomic particles that determine how atoms interact and bond with each other in chemical reactions. The arrangement of electrons in the outermost shell determines the chemical properties of an element. Electrons are negatively charged, have negligible mass, and revolve around the nucleus in shells.', sectionId: 4 },
    { id: 9, type: 'single_word', marks: 1, question: 'What is the symbol, mass number, and atomic number of Oxygen?', answer: 'Symbol: O, Mass number: 16, Atomic number: 8', reexplanation: 'Oxygen: Symbol = O, Atomic number (Z) = 8 (8 protons, 8 electrons), Mass number (A) = 16. Neutrons = A−Z = 16−8 = 8 neutrons. Electronic configuration: K=2, L=6. This element is essential for respiration and is the most abundant element in the Earth\'s crust.', sectionId: 4 },
    { id: 10, type: 'single_word', marks: 1, question: 'An atom has 12 electrons and 13 neutrons. What is its mass number?', answer: 'Mass number = 25 (Z=12, n=13, A = p+n = 12+13 = 25)', reexplanation: 'Since the atom has 12 electrons and atoms are neutral, it has 12 protons. Atomic number Z = 12. Mass number A = protons + neutrons = 12 + 13 = 25. This element with Z=12 is Magnesium (Mg), but this particular atom has A=25 (isotope of Mg).', sectionId: 4 },
    { id: 11, type: 'sentence', marks: 2, question: 'Use the phrase "atomic number" in a sentence explaining why it uniquely identifies each element.', answer: 'The atomic number uniquely identifies each element because it is the number of protons in the nucleus — and changing the number of protons creates an entirely different element: carbon has 6 protons, nitrogen has 7, and they have completely different properties despite being just one proton apart.', hint: 'Atomic number Z = number of protons. Each element has a unique atomic number. Change the proton count → different element entirely.', reexplanation: 'Every element has a unique atomic number — no two elements can have the same number of protons. Carbon (Z=6) and Nitrogen (Z=7) differ by just one proton but are completely different substances with different properties, chemical behaviours, and biological roles.', sectionId: 5 },
    { id: 12, type: 'sentence', marks: 2, question: 'Use the words "K shell", "L shell", and "M shell" in a sentence about the electronic configuration of Magnesium.', answer: 'Magnesium (Z=12) has its 12 electrons arranged across three shells: 2 electrons in the K shell (first shell, maximum 2), 8 electrons in the L shell (second shell, maximum 8), and 2 electrons in the M shell (third shell, maximum 18).', hint: 'Mg: Z=12, A=24. Shells: K(2), L(8), M(2) — total = 12 electrons. K max=2, L max=8, M max=18.', reexplanation: 'Magnesium (Z=12) electronic configuration: K=2, L=8, M=2. The K shell is filled first (2/2), then L shell (8/8 full), and the remaining 2 electrons go into the M shell. Neutrons = A−Z = 24−12 = 12.', sectionId: 5 },
    { id: 13, type: 'sentence', marks: 2, question: 'Use the phrase "Neil Bohr" in a sentence about the modern atomic model.', answer: 'Neil Bohr proposed the modern atomic model in which electrons revolve around a central nucleus in specific, imaginary paths called shells or orbits — K, L, M, N — each with a maximum number of electrons it can hold.', hint: 'Neil Bohr (1940) proposed: nucleus (protons+neutrons) in centre; electrons revolve in shells/orbits (K, L, M, N) around nucleus.', reexplanation: 'Neil Bohr\'s model of the atom (modern concept) states: the nucleus is at the centre containing protons and neutrons; electrons revolve around the nucleus in defined, imaginary paths called shells or orbits (K, L, M, N); each shell can hold a maximum of 2n² electrons.', sectionId: 5 },
    { id: 14, type: 'sentence', marks: 2, question: 'Use the formula 2n² to calculate the maximum electrons in the M shell.', answer: 'Using the formula 2n², where n=3 for the M shell (third shell): maximum electrons = 2×3² = 2×9 = 18 electrons — so the M shell can hold a maximum of 18 electrons.', hint: 'M shell = third shell, n=3. Formula: 2n². Max = 2 × 3² = 2 × 9 = 18 electrons.', reexplanation: 'The formula for maximum electrons in a shell is 2n², where n is the shell number. K (n=1): 2×1=2. L (n=2): 2×4=8. M (n=3): 2×9=18. N (n=4): 2×16=32. Each shell fills before the next one begins to fill.', sectionId: 5 },
    { id: 15, type: 'sentence', marks: 2, question: 'Use the word "Kanada" in a sentence about India\'s contribution to atomic theory.', answer: 'The ancient Indian sage Kanada, around 600 B.C., was perhaps the first in history to propose that all matter is made of tiny, indivisible particles he called parmanu or anu — a concept that predated the modern atomic theory of John Dalton by more than 2,000 years.', hint: 'Kanada = ancient Indian sage (around 600 B.C.). Proposed that all matter is made of tiny particles called parmanu or anu. Predates Dalton\'s atomic theory by 2000+ years.', reexplanation: 'India\'s contribution to atomic theory: Sage Kanada proposed the concept of parmanu (indivisible particle) around 600 B.C. This is a remarkably accurate precursor to the modern atomic theory. John Dalton proposed his atomic theory in 1808 — more than 2,400 years after Kanada.', sectionId: 5 },
    { id: 16, type: 'long_answer', marks: 5, question: 'Describe the structure of an atom. Include: the three subatomic particles (with charge and mass), the atomic number and mass number formulas, and the electronic configuration of Chlorine (Z=17, A=35).', answer: 'An atom consists of a central nucleus surrounded by electrons revolving in shells. The three subatomic particles are: (1) Proton — found in the nucleus; charge = +1; mass = 1 atomic mass unit. (2) Neutron — found in the nucleus; charge = 0 (neutral); mass = 1 atomic mass unit. (3) Electron — revolves around the nucleus in shells; charge = −1; mass ≈ 0 (negligible). The atomic number Z = number of protons = number of electrons (Z = p = e). The mass number A = protons + neutrons (A = p + n). Therefore, neutrons = A − Z. For Chlorine (Z=17, A=35): Number of protons = 17, Number of electrons = 17, Number of neutrons = 35 − 17 = 18. Electronic configuration: Fill K shell first (max 2): K=2. Remaining: 17−2=15. Fill L shell (max 8): L=8. Remaining: 15−8=7. Fill M shell with remaining: M=7. So Chlorine: K=2, L=8, M=7.', hint: 'Three particles: proton (+1, mass 1, in nucleus), neutron (0, mass 1, in nucleus), electron (−1, mass 0, in shells). Z=p=e. A=p+n. For Cl: Z=17, A=35, n=18, config=K:2, L:8, M:7.', reexplanation: 'Complete answer: (1) Proton: +1, mass 1, nucleus; (2) Neutron: 0, mass 1, nucleus; (3) Electron: −1, mass≈0, shells. Z=p=e; A=p+n; n=A−Z. For ³⁵₁₇Cl: protons=17, electrons=17, neutrons=18, electronic configuration K=2, L=8, M=7.', sectionId: 7 },
  ],
}

const q6: ChapterQuiz = {
  chapterId: 6, title: 'Physical and Chemical Changes', totalMarks: 25,
  questions: [
    { id: 1, type: 'mcq', marks: 1, question: 'Which of the following is a CHEMICAL change?', options: [{ label: 'A', text: 'Melting of ice' }, { label: 'B', text: 'Stretching a rubber band' }, { label: 'C', text: 'Rusting of iron' }, { label: 'D', text: 'Dissolving salt in water' }], answer: 'C', reexplanation: 'Rusting of iron is a chemical change — a new substance (iron oxide/rust) is formed, and the original iron cannot be recovered. Melting of ice, stretching a rubber band, and dissolving salt in water are all physical changes — no new substance is formed and they are reversible.' },
    { id: 2, type: 'mcq', marks: 1, question: 'What is the key difference between a physical and a chemical change?', options: [{ label: 'A', text: 'Physical changes are slow; chemical changes are fast' }, { label: 'B', text: 'In a physical change, a new substance is formed; in chemical, no new substance' }, { label: 'C', text: 'In a chemical change, a new substance is formed; physical change forms no new substance' }, { label: 'D', text: 'Chemical changes occur with water; physical changes do not' }], answer: 'C', reexplanation: 'The key difference: in a chemical change, a new substance (or substances) is formed. In a physical change, no new substance is formed — only the shape, size, or state of the original substance changes. Chemical changes are usually irreversible; physical changes are usually reversible.' },
    { id: 3, type: 'mcq', marks: 1, question: 'Which of the following accompanies a chemical reaction?', options: [{ label: 'A', text: 'Change in shape only' }, { label: 'B', text: 'Change in size' }, { label: 'C', text: 'Change in colour or release of gas' }, { label: 'D', text: 'Change in physical state' }], answer: 'C', reexplanation: 'Chemical reactions are accompanied by: (1) release or absorption of heat or light, (2) evolution of a gas, (3) production of sound, (4) change in smell, (5) change in colour. Changes in shape, size, and physical state are signs of physical changes, not chemical ones.' },
    { id: 4, type: 'mcq', marks: 1, question: 'What is an exothermic change?', options: [{ label: 'A', text: 'A change that absorbs heat from surroundings' }, { label: 'B', text: 'A change that releases heat to the surroundings' }, { label: 'C', text: 'A change in which colour is produced' }, { label: 'D', text: 'A reversible physical change' }], answer: 'B', reexplanation: 'An exothermic change releases heat energy to the surroundings — the surroundings become warmer. Examples: burning a matchstick, dissolving quicklime (calcium oxide) in water, dissolving caustic soda (sodium hydroxide) in water, rotting of vegetable matter to form compost. Endothermic changes absorb heat from the surroundings.' },
    { id: 5, type: 'mcq', marks: 1, question: 'Mixing vinegar and baking powder is:', options: [{ label: 'A', text: 'A physical change — no new substance formed' }, { label: 'B', text: 'A chemical change — CO₂ gas is evolved (a new substance)' }, { label: 'C', text: 'A physical change because it is reversible' }, { label: 'D', text: 'Not a change at all' }], answer: 'B', reexplanation: 'Mixing vinegar and baking powder produces a chemical change — CO₂ gas is evolved (you can see it fizzing). This gas turns lime water milky, confirming it is CO₂. A new substance (carbon dioxide) is formed. The original baking powder and vinegar cannot be recovered. Chemical changes produce new substances and are usually irreversible.' },
    { id: 6, type: 'single_word', marks: 1, question: 'What is sublimation?', answer: 'A physical change in which a solid converts directly into gas without passing through the liquid state', reexplanation: 'Sublimation is a physical change where a solid changes directly to a gas (or vapour) without first becoming a liquid. Examples: camphor sublimes directly to vapour when exposed to air. Dry ice (solid CO₂) sublimes directly to CO₂ gas. Naphthalene (mothballs) sublimes. Since no new substance is formed, it is a physical change.', sectionId: 4 },
    { id: 7, type: 'single_word', marks: 1, question: 'What is the colour of ferrous sulphate — the product formed when iron is placed in copper sulphate solution?', answer: 'Green (Ferrous sulphate is green; copper is reddish-brown)', reexplanation: 'When an iron nail is placed in blue copper sulphate solution, a chemical change occurs: Copper sulphate (blue) + Iron → Ferrous sulphate (green) + Copper (reddish-brown). The blue solution turns green (ferrous sulphate forms) and reddish-brown copper deposits on the iron nail. This colour change is a sign of a chemical reaction.', sectionId: 4 },
    { id: 8, type: 'single_word', marks: 1, question: 'Name three conditions required for a chemical change to occur.', answer: 'Any three from: (1) substances must be in contact, (2) formation of a solution, (3) presence of heat, (4) presence of light, (5) passing electric current', reexplanation: 'Five conditions required for chemical changes: (1) Substances must be in contact (iron + moist air for rusting); (2) Formation of a solution (iron + copper sulphate solution); (3) Presence of heat (food cooks, paper burns); (4) Presence of light (photosynthesis only in sunlight); (5) Passing electric current (water breaks into H₂ and O₂).', sectionId: 4 },
    { id: 9, type: 'single_word', marks: 1, question: 'What is Pasteurisation, and who invented it?', answer: 'Pasteurisation is the process of heating milk to a high temperature and quickly cooling it to kill microbes. Invented by Louis Pasteur.', reexplanation: 'Louis Pasteur discovered that milk turns sour because of microbes (tiny organisms). He found that heating milk to a high temperature and quickly cooling it kills these microbes. This technique — Pasteurisation — is why we can safely store milk. It is based on our understanding of chemical change in biological systems.', sectionId: 4 },
    { id: 10, type: 'single_word', marks: 1, question: 'What chemical change does the equation Magnesium + Oxygen → represent?', answer: 'Magnesium + Oxygen → Magnesium oxide (white ash). Burning of magnesium ribbon — a chemical change', reexplanation: 'When a magnesium ribbon is held in the flame of a burner, it burns with a dazzling white flame, producing white ash called magnesium oxide (MgO). Mg + O₂ → MgO. This is a chemical change: a new substance (magnesium oxide) is formed, and the original magnesium ribbon cannot be recovered.', sectionId: 4 },
    { id: 11, type: 'sentence', marks: 2, question: 'Use the words "reversible" and "irreversible" in a sentence contrasting two examples.', answer: 'Melting ice is a reversible physical change because you can freeze the water back to ice, while burning wood is an irreversible chemical change because the ash and gases produced cannot be converted back to the original wood.', hint: 'Reversible = physical changes (melting, boiling, dissolving). Irreversible = chemical changes (burning, rusting, cooking). Reversible = can be undone. Irreversible = cannot be undone.', reexplanation: 'Physical changes are reversible (melting → freezing, dissolving → evaporating the solvent). Chemical changes are irreversible (burning → ash cannot be turned back to wood; rusting → rust cannot become shiny iron again; cooking → cooked food cannot become raw again).', sectionId: 5 },
    { id: 12, type: 'sentence', marks: 2, question: 'Use the word "rusting" in a sentence explaining why it is a chemical change.', answer: 'Rusting is a chemical change because a new substance — reddish-brown iron oxide (rust) — is formed when iron reacts with oxygen and moisture in the air, and this process is irreversible since rusted iron cannot be restored to its original shiny state.', hint: 'Rusting = iron + oxygen + moisture → iron oxide (rust). New substance formed. Irreversible. Chemical change.', reexplanation: 'Rusting is definitely a chemical change: (1) a new substance (iron oxide) is formed; (2) the process is irreversible — you cannot turn rust back to shiny iron easily; (3) it is accompanied by a colour change (silver-grey iron → reddish-brown rust). Conditions: iron must be in contact with both oxygen and moisture.', sectionId: 5 },
    { id: 13, type: 'sentence', marks: 2, question: 'Use the phrase "evolution of gas" in a sentence about a chemical reaction you can observe at home.', answer: 'Evolution of gas — the production and release of bubbles of gas — is evidence of a chemical reaction: when vinegar is mixed with baking soda at home, CO₂ gas is evolved with a fizzing sound, and passing this gas through lime water turns the lime water milky, confirming the new substance formed.', hint: 'Evolution of gas = a new gas is produced during a chemical reaction. Example: vinegar + baking powder → CO₂ gas evolved (fizzing). Lime water test: CO₂ turns lime water milky.', reexplanation: 'The vinegar + baking soda reaction is a classic home chemistry experiment demonstrating gas evolution. Acetic acid (vinegar) reacts with sodium bicarbonate (baking soda) to produce sodium acetate, water, and carbon dioxide gas. The CO₂ creates the fizzing effect — a clear sign of a chemical change.', sectionId: 5 },
    { id: 14, type: 'sentence', marks: 2, question: 'Use the word "exothermic" in a sentence about two examples from daily life.', answer: 'Exothermic changes are chemical changes that release heat — burning a matchstick (which produces heat and light) and dissolving quicklime in water (which makes the water very hot) are two common examples of exothermic changes encountered in daily life.', hint: 'Exothermic = releases heat. Examples: burning matchstick, dissolving quicklime in water, dissolving caustic soda in water, adding acid to water, rotting vegetable matter (compost).', reexplanation: 'Exothermic changes release heat energy to the surroundings. In everyday life: burning anything (matches, candles, gas stoves) is exothermic. Dissolving quicklime (CaO) in water produces calcium hydroxide and a LOT of heat — the beaker becomes very hot. Hand warmers use exothermic chemical reactions to produce heat.', sectionId: 5 },
    { id: 15, type: 'sentence', marks: 2, question: 'Use the phrase "physical change" in a sentence listing four examples of physical changes involving states of matter.', answer: 'Physical changes involving states of matter include melting (solid to liquid), vaporisation (liquid to vapour), condensation (gas to liquid), and freezing (liquid to solid) — all of which are reversible and produce no new substance.', hint: 'Physical changes (states of matter): melting, vaporisation, condensation, freezing, sublimation, dissolution of solute in solvent.', reexplanation: 'Changes of state are all physical changes: melting (solid→liquid, e.g., ice melting), vaporisation (liquid→gas, e.g., water boiling), condensation (gas→liquid, e.g., water vapour condensing on a cold surface), freezing (liquid→solid, e.g., water freezing to ice), sublimation (solid→gas, e.g., camphor). All reversible, no new substance.', sectionId: 5 },
    { id: 16, type: 'long_answer', marks: 5, question: 'Write 4 differences between physical and chemical changes, giving two examples of each.', answer: 'Physical vs Chemical Changes:\n1. New substance: In a physical change, no new substance is formed. In a chemical change, a new substance is always formed. Physical examples: ice melting to water, rubber band stretching. Chemical examples: burning wood produces ash and gases, iron rusting produces iron oxide.\n2. Reversibility: Physical changes are usually reversible. Chemical changes are usually irreversible. Physical: water can be frozen back to ice. Chemical: ash cannot be turned back to wood; rust cannot be turned back to shiny iron.\n3. Accompanying signs: Physical change is accompanied by change in shape, size, or state of matter. Chemical change is accompanied by change in colour, release of heat/light, evolution of gas, change in smell, or production of sound. Physical: melting (state change), stretching (shape change). Chemical: magnesium burns with white light (heat+light), vinegar+baking soda fizzes (gas evolved).\n4. Permanence: Most physical changes are temporary. Most chemical changes are permanent. Physical: ice melts (temporary — can be refrozen). Chemical: cooked egg cannot become raw again (permanent).', hint: '4 differences: (1) new substance formed or not; (2) reversible or not; (3) what accompanies the change (shape/size/state vs colour/heat/gas/sound/smell); (4) temporary or permanent.', reexplanation: 'Four differences: (1) New substance: Physical=no, Chemical=yes. (2) Reversible: Physical=usually yes, Chemical=usually no. (3) Signs: Physical=change in shape/size/state; Chemical=colour change, heat/light, gas, smell, sound. (4) Permanence: Physical=usually temporary, Chemical=usually permanent. Two examples each.', sectionId: 7 },
  ],
}

const q7: ChapterQuiz = {
  chapterId: 7, title: 'Cell – The Basic Unit of Life', totalMarks: 25,
  questions: [
    { id: 1, type: 'mcq', marks: 1, question: 'Who first observed and named cells?', options: [{ label: 'A', text: 'Louis Pasteur' }, { label: 'B', text: 'Robert Hooke' }, { label: 'C', text: 'Neil Bohr' }, { label: 'D', text: 'Antoine Lavoisier' }], answer: 'B', reexplanation: 'Robert Hooke first observed cells in 1665. He examined thin slices of cork under a compound microscope and saw tiny pores that looked like the walled compartments a monk would live in. He called them "cells" — from the Latin word "cella" meaning small room. However, Hooke did not know the function or structure of cells.' },
    { id: 2, type: 'mcq', marks: 1, question: 'Why is the mitochondria called the powerhouse of the cell?', options: [{ label: 'A', text: 'Because it controls cell division' }, { label: 'B', text: 'Because it makes proteins' }, { label: 'C', text: 'Because it helps in cellular respiration and release of energy' }, { label: 'D', text: 'Because it stores genetic information' }], answer: 'C', reexplanation: 'Mitochondria are called the powerhouse of the cell because they are responsible for cellular respiration — the process by which food (glucose) is broken down using oxygen to release energy in the form of ATP (the cell\'s energy currency). Every activity in the cell requires energy that the mitochondria produce.' },
    { id: 3, type: 'mcq', marks: 1, question: 'Which organelle is ONLY found in plant cells (not animal cells)?', options: [{ label: 'A', text: 'Mitochondria' }, { label: 'B', text: 'Ribosomes' }, { label: 'C', text: 'Centrosome' }, { label: 'D', text: 'Plastids (chloroplasts)' }], answer: 'D', reexplanation: 'Plastids (including chloroplasts) are found ONLY in plant cells and are absent in animal cells. Similarly, the cell wall is only in plant cells. The centrosome is found ONLY in animal cells (absent in plant cells). Mitochondria and ribosomes are found in BOTH plant and animal cells.' },
    { id: 4, type: 'mcq', marks: 1, question: 'Why are lysosomes called "suicide bags"?', options: [{ label: 'A', text: 'Because they produce energy that can destroy the cell' }, { label: 'B', text: 'Because they contain digestive enzymes that can digest and destroy the whole cell' }, { label: 'C', text: 'Because they control cell division' }, { label: 'D', text: 'Because they are found only in dying cells' }], answer: 'B', reexplanation: 'Lysosomes are called "suicide bags" because they contain powerful digestive enzymes. Normally, these enzymes digest food, foreign particles, and waste in the cell. But if the lysosome\'s membrane ruptures, the enzymes are released into the cytoplasm and can digest and destroy the entire cell — hence the nickname "suicide bags."' },
    { id: 5, type: 'mcq', marks: 1, question: 'What is the function of the nucleus?', options: [{ label: 'A', text: 'Produces energy for the cell' }, { label: 'B', text: 'Makes proteins for the cell' }, { label: 'C', text: 'Controls all functions of the cell and helps transmit characteristics to offspring' }, { label: 'D', text: 'Provides rigidity and shape to the cell' }], answer: 'C', reexplanation: 'The nucleus controls all functions of the cell — it is the control centre. It also contains chromosomes which carry genes that transmit characteristics (like eye colour, height) from parents to offspring. Cell wall provides rigidity (in plants), mitochondria produce energy, and ribosomes make proteins.' },
    { id: 6, type: 'single_word', marks: 1, question: 'What is the "powerhouse" of the cell?', answer: 'Mitochondria', reexplanation: 'Mitochondria are the powerhouse of the cell. They are double-membrane bag-like structures that carry out cellular respiration — breaking down food in the presence of oxygen to release energy. This energy is used for all cellular activities including growth, movement, and protein synthesis.', sectionId: 4 },
    { id: 7, type: 'single_word', marks: 1, question: 'Name the organelle responsible for protein synthesis.', answer: 'Ribosomes', reexplanation: 'Ribosomes are spherical granular particles involved in protein synthesis — making proteins from amino acids. Ribosomes can occur freely in the cytoplasm or remain attached to the endoplasmic reticulum (forming rough ER). Every cell needs proteins for structure and function, so ribosomes are essential in all living cells.', sectionId: 4 },
    { id: 8, type: 'single_word', marks: 1, question: 'What are chromosomes and what do they carry?', answer: 'Thread-like structures in the nucleus that carry genes — which control the characteristics (like hair colour, height) of an organism and are passed from parents to offspring', reexplanation: 'Chromosomes are thread-like structures made of DNA that are found in the nucleus of every cell. They carry genes — the units of hereditary information. Each chromosome carries thousands of genes that control every characteristic of the organism. Chromosomes are passed from parents to offspring through reproduction.', sectionId: 4 },
    { id: 9, type: 'single_word', marks: 1, question: 'What type of plastid contains green pigment chlorophyll?', answer: 'Chloroplast', reexplanation: 'Chloroplasts contain the green pigment chlorophyll which traps solar (light) energy for performing photosynthesis. During photosynthesis, chloroplasts use sunlight, carbon dioxide, and water to produce glucose (food) and oxygen. Chloroplasts are found only in plant cells and give plants their characteristic green colour.', sectionId: 4 },
    { id: 10, type: 'single_word', marks: 1, question: 'Name 4 differences between plant cell and animal cell.', answer: 'Animal cell: no cell wall, no plastids, vacuoles small and many, centrosome present. Plant cell: has cellulose cell wall, has plastids, vacuoles large and few, centrosome absent.', reexplanation: 'Four differences: (1) Cell wall: Animal=absent, Plant=cellulose cell wall present; (2) Plastids: Animal=absent, Plant=present (chloroplasts, chromoplasts, leucoplasts); (3) Vacuoles: Animal=many but small and temporary, Plant=few but large and prominent; (4) Centrosome: Animal=present (regulates cell division), Plant=absent.', sectionId: 4 },
    { id: 11, type: 'sentence', marks: 2, question: 'Use the phrase "cell wall" in a sentence explaining why plants can stand upright.', answer: 'Plant cells have a rigid cellulose cell wall outside the cell membrane that provides rigidity and shape, which is why plants can stand upright on their own without a skeletal system like animals — the combined strength of millions of cell walls supports the plant\'s structure.', hint: 'Cell wall: only in plant cells; outside cell membrane; provides rigidity and shape; helps cell bear unfavourable conditions. Animal cells have no cell wall.', reexplanation: 'The cellulose cell wall in plant cells provides structural support. Unlike animals which have bones, plants rely on the combined rigidity of their cell walls for support. The cell wall is made of cellulose — a tough, fibrous material. It also protects the cell from unfavourable conditions.', sectionId: 5 },
    { id: 12, type: 'sentence', marks: 2, question: 'Use the word "chloroplast" in a sentence about photosynthesis.', answer: 'Chloroplasts, found only in plant cells, contain the green pigment chlorophyll which captures solar energy to power photosynthesis — converting carbon dioxide and water into glucose (food) and oxygen.', hint: 'Chloroplast: plastid, only in plant cells, contains chlorophyll (green pigment), traps solar energy for photosynthesis.', reexplanation: 'Chloroplasts are the sites of photosynthesis in plant cells. They contain chlorophyll which absorbs sunlight. Using this energy, CO₂ from the air and water from the roots are combined to produce glucose (the plant\'s food) and oxygen (released into the air). This is the foundation of virtually all food chains on Earth.', sectionId: 5 },
    { id: 13, type: 'sentence', marks: 2, question: 'Use the word "gene" in a sentence about heredity and why children resemble their parents.', answer: 'Genes — carried on chromosomes in the nucleus of every cell — control all the inherited characteristics of an organism, from hair and eye colour to height and certain behaviours, which is why children resemble their parents because they inherit their chromosomes (and hence their genes) from them.', hint: 'Genes are on chromosomes in the nucleus. Genes carry characteristics (hair colour, height, eye colour). Chromosomes are passed from parents to offspring → children inherit genes → children resemble parents.', reexplanation: 'Genes are the units of hereditary information encoded in DNA. They are carried on chromosomes in the nucleus. During reproduction, chromosomes are passed from parents to offspring — half from the mother and half from the father. The inherited genes determine the characteristics of the offspring, which is why children resemble (but are not identical to) their parents.', sectionId: 5 },
    { id: 14, type: 'sentence', marks: 2, question: 'Use the word "vacuole" in a sentence comparing plant and animal cells.', answer: 'In plant cells, vacuoles are large, few in number, and prominent — they store water, food, and help maintain the cell\'s shape — while in animal cells, vacuoles are many but small, scattered throughout the cytoplasm.', hint: 'Vacuoles: Plant cells = few but large and prominent (store food and water, maintain shape). Animal cells = many but small and temporary.', reexplanation: 'Vacuoles are fluid-filled sacs. In plant cells, the central vacuole can take up 90% of the cell\'s volume and plays a major role in maintaining the cell\'s shape (turgor pressure) and storing water and nutrients. In animal cells, vacuoles are smaller and more numerous, functioning mainly in waste removal and temporary storage.', sectionId: 5 },
    { id: 15, type: 'sentence', marks: 2, question: 'Use the phrase "Golgi apparatus" in a sentence explaining its function.', answer: 'The Golgi apparatus — a stack of flattened sacs resembling a pile of coins — functions as the packaging and shipping centre of the cell, helping in the formation of the cell wall and the synthesis and secretion of proteins.', hint: 'Golgi apparatus: flattened sacs, stacked like pile of coins; helps in formation of cell wall; synthesis and secretion of proteins.', reexplanation: 'The Golgi apparatus is often described as the cell\'s post office or packaging centre. It receives proteins from the endoplasmic reticulum, modifies them, packages them into vesicles, and ships them to their destination — either for use within the cell or for secretion outside the cell. It also helps form the cell wall in plant cells.', sectionId: 5 },
    { id: 16, type: 'long_answer', marks: 5, question: 'Name any 8 organelles of a cell and describe the function of each.', answer: '1. Cell Membrane: The outermost covering of the animal cell. Functions: provides and maintains shape; regulates transportation of materials into and out of the cell.\n2. Cell Wall: Present only in plant cells, outside the cell membrane. Functions: provides rigidity and shape; helps cell bear unfavourable conditions.\n3. Nucleus: Control centre of the cell. Functions: controls all functions of the cell; contains chromosomes with genes that transmit characteristics from parents to offspring.\n4. Mitochondria: Double membrane bag-like structures. Functions: cellular respiration and release of energy; called the powerhouse of the cell.\n5. Ribosomes: Spherical granular particles. Function: protein synthesis.\n6. Golgi Apparatus: Flattened sacs stacked like a pile of coins. Functions: helps form cell wall; synthesis and secretion of proteins.\n7. Lysosomes: Sac-like structures. Functions: contain digestive enzymes; digest food, foreign particles; called suicide bags as they can destroy the whole cell.\n8. Chloroplasts (Plastids): Found only in plant cells. Function: contain chlorophyll; trap solar energy for photosynthesis.', hint: 'Choose any 8 from: cell membrane, cell wall, nucleus, mitochondria, ribosomes, Golgi apparatus, lysosomes, plastids/chloroplasts, endoplasmic reticulum, vacuoles, centrosome. Name + function for each.', reexplanation: 'Any 8 organelles with clear functions. Key facts: Mitochondria=powerhouse (energy/respiration); Ribosomes=protein synthesis; Nucleus=control centre+heredity; Golgi=packaging+secretion; Lysosomes=digestion+suicide bags; Chloroplast=photosynthesis; Cell wall=rigidity (plant only); Centrosome=cell division (animal only); ER=protein transport; Vacuoles=storage.', sectionId: 7 },
  ],
}

const q8: ChapterQuiz = {
  chapterId: 8, title: 'The Leaf', totalMarks: 25,
  questions: [
    { id: 1, type: 'mcq', marks: 1, question: 'What is the main function of the lamina of a leaf?', options: [{ label: 'A', text: 'Attaches the leaf to the stem' }, { label: 'B', text: 'Manufactures food through photosynthesis' }, { label: 'C', text: 'Transports water to roots' }, { label: 'D', text: 'Stores starch for the plant' }], answer: 'B', reexplanation: 'The lamina (leaf blade) is the wide, flat, green portion of the leaf and is the most important part — food is manufactured here through photosynthesis. The lamina contains chlorophyll which captures solar energy to convert CO₂ and water into glucose. The petiole attaches the leaf to the stem; veins transport water and minerals.' },
    { id: 2, type: 'mcq', marks: 1, question: 'Which type of venation has veins arranged in a network?', options: [{ label: 'A', text: 'Parallel venation' }, { label: 'B', text: 'Alternate venation' }, { label: 'C', text: 'Reticulate venation' }, { label: 'D', text: 'Whorled venation' }], answer: 'C', reexplanation: 'Reticulate venation has veins arranged in the form of a network (like a net). Example: peepal leaf. Parallel venation has veins arranged parallel to each other — found in grass, maize, paddy. Alternate and whorled refer to types of phyllotaxy (leaf arrangement on stem), not venation.' },
    { id: 3, type: 'mcq', marks: 1, question: 'Jasmine plant has which type of phyllotaxy?', options: [{ label: 'A', text: 'Alternate' }, { label: 'B', text: 'Whorled' }, { label: 'C', text: 'Opposite' }, { label: 'D', text: 'Reticulate' }], answer: 'C', reexplanation: 'Jasmine has opposite phyllotaxy — two leaves are arranged on one node, exactly opposite each other. Alternate phyllotaxy has one leaf per node (examples: mustard, sunflower, rose). Whorled phyllotaxy has three or more leaves per node (example: oleander). Reticulate refers to venation pattern, not phyllotaxy.' },
    { id: 4, type: 'mcq', marks: 1, question: 'A leaf tendril is a modification seen in:', options: [{ label: 'A', text: 'Onion' }, { label: 'B', text: 'Prickly pear (opuntia)' }, { label: 'C', text: 'Pea plant' }, { label: 'D', text: 'Bryophyllum' }], answer: 'C', reexplanation: 'In pea plants, the leaf is modified into a thin, wire-like, coiled structure called a tendril. The tendril helps the plant climb up by coiling around a support. Onion has scale leaves (store food). Prickly pear has leaf spines (reduce water loss). Bryophyllum has leaves with buds for reproduction.' },
    { id: 5, type: 'mcq', marks: 1, question: 'What is transpiration?', options: [{ label: 'A', text: 'The process of making food in leaves' }, { label: 'B', text: 'The exchange of gases through stomata' }, { label: 'C', text: 'The loss of water vapour from leaves through stomata' }, { label: 'D', text: 'The absorption of water by roots' }], answer: 'C', reexplanation: 'Transpiration is the process by which plants lose water through stomata in leaves in the form of water vapour. This process controls the water content of the plant and also cools the plant and its surroundings. The Urban Heat Island Effect in cities is partly due to lack of trees and therefore lack of transpiration.' },
    { id: 6, type: 'single_word', marks: 1, question: 'What is phyllotaxy?', answer: 'The arrangement of leaves on the stem or branches of a plant', reexplanation: 'Phyllotaxy is the arrangement of leaves on the stem or branches of a plant. It prevents leaves from overlapping so that each leaf gets sufficient sunlight for photosynthesis. The three types are: alternate (one leaf per node), opposite (two leaves per node), and whorled (three or more leaves per node).', sectionId: 4 },
    { id: 7, type: 'single_word', marks: 1, question: 'What is a compound leaf? Give one example.', answer: 'A compound leaf is one where the lamina is divided into a number of small leaves called leaflets. Example: rose or mimosa', reexplanation: 'In a compound leaf, the lamina (leaf blade) is divided into a number of small leaf-like units called leaflets. Examples: rose (leaflets arranged along a central axis), mimosa, neem. In contrast, a simple leaf has an undivided lamina (like peepal, mango). The difference is whether the lamina is divided into leaflets or not.', sectionId: 4 },
    { id: 8, type: 'single_word', marks: 1, question: 'What is the Urban Heat Island Effect?', answer: 'The phenomenon where cities become hotter than surrounding rural areas because buildings made of glass and concrete trap and reflect heat instead of absorbing it', reexplanation: 'The Urban Heat Island Effect is the measurable difference in temperature between cities (with glass, concrete, asphalt) and surrounding rural areas (with vegetation). Glass and concrete reflect and trap heat, while trees and plants cool through transpiration and shade. Areas with more trees feel cooler — which is why planting trees in cities is an important climate strategy.', sectionId: 4 },
    { id: 9, type: 'single_word', marks: 1, question: 'Name the scientist who invented the Crescograph.', answer: 'Sir Jagdish Chandra Bose', reexplanation: 'Sir Jagdish Chandra Bose (1858–1937) was an Indian scientist who made major discoveries in plant physiology. He discovered the existence of a nervous system in plants and invented the Crescograph — a device for measuring extremely small amounts of plant growth. He used the mimosa plant for his research because it is directly sensitive to the Sun.', sectionId: 4 },
    { id: 10, type: 'single_word', marks: 1, question: 'Name three modifications of leaves and the plant they are found in.', answer: 'Tendril (pea plant), Spines (prickly pear/opuntia), Scale leaves (onion), Reproduction buds (Bryophyllum/Begonia), Insectivorous (pitcher plant/Venus fly trap)', reexplanation: 'Leaf modifications: (1) Leaf tendril in pea plant — helps the plant climb; (2) Leaf spines in prickly pear — reduce water loss and provide protection; (3) Scale leaves in onion — store food and protect buds; (4) Reproductive buds in Bryophyllum/Begonia — buds on leaves produce new plants; (5) Insect-trapping structures in pitcher plant and Venus fly trap — trap insects for nitrogen.', sectionId: 4 },
    { id: 11, type: 'sentence', marks: 2, question: 'Use the word "stomata" in a sentence explaining two functions of leaves.', answer: 'Stomata are tiny pores on leaves that serve two crucial functions: they allow gaseous exchange (taking in CO₂ and releasing O₂ during photosynthesis, and the reverse during respiration) and they enable transpiration — the release of water vapour from the plant, which cools both the plant and its surroundings.', hint: 'Stomata = tiny pores on leaves. Two functions: (1) Gaseous exchange (CO₂ in, O₂ out during photosynthesis); (2) Transpiration (water vapour out, cools the plant).', reexplanation: 'Stomata are microscopic pores on the leaf surface (mainly the lower surface). They serve as the gateway for two critical leaf functions: (1) Gaseous exchange — CO₂ enters for photosynthesis, O₂ is released; during respiration, the opposite occurs. (2) Transpiration — water vapour exits, cooling the plant and contributing to the water cycle.', sectionId: 5 },
    { id: 12, type: 'sentence', marks: 2, question: 'Use the word "chlorophyll" in a sentence about photosynthesis.', answer: 'Chlorophyll — the green pigment found in chloroplasts of plant cells — captures solar energy and uses it to power photosynthesis, the process by which carbon dioxide and water are converted into glucose (food) and oxygen.', hint: 'Chlorophyll = green pigment in chloroplasts. It traps solar energy. Photosynthesis: CO₂ + H₂O + sunlight (via chlorophyll) → glucose + O₂.', reexplanation: 'Chlorophyll is the key pigment in photosynthesis. It absorbs red and blue light from sunlight and uses this energy to power the chemical reaction: 6CO₂ + 6H₂O + light energy → C₆H₁₂O₆ + 6O₂. The green colour of plants comes from chlorophyll reflecting the green part of sunlight.', sectionId: 5 },
    { id: 13, type: 'sentence', marks: 2, question: 'Use the phrase "insectivorous plant" in a sentence with one example explaining how the leaf modification works.', answer: 'An insectivorous plant modifies its leaves into special structures to trap and digest insects for nitrogen — in the pitcher plant, the leaf blade becomes a pitcher-shaped trap with a lid, attracting insects which fall in and are digested.', hint: 'Insectivorous plants: pitcher plant (leaf becomes pitcher, traps insects for nitrogen), Venus fly trap (leaf blade in two hinged halves that close when touched).', reexplanation: 'Insectivorous plants live in nitrogen-poor soils and have evolved to trap insects to supplement their nitrogen intake. In the pitcher plant (Nepenthes), the leaf lamina becomes modified into a pitcher, the petiole becomes a thin coiled structure, and the leaf tip forms a lid — attracting, drowning, and digesting insects with enzymes in the pitcher fluid.', sectionId: 5 },
    { id: 14, type: 'sentence', marks: 2, question: 'Use the phrase "reticulate venation" in a sentence with one example explaining why it is called reticulate.', answer: 'Reticulate venation is called "reticulate" because the veins in the leaf are arranged in the form of a network (like a net) — as seen clearly in a peepal leaf where veins branch repeatedly and interconnect to form a net-like pattern.', hint: 'Reticulate = network pattern. Veins arranged in net-like pattern. Example: peepal, mango, rose. Compare with parallel venation (grass, maize, paddy) where veins run parallel.', reexplanation: 'The word "reticulate" comes from the Latin "reticulum" meaning little net. In reticulate venation, the veins branch from the midrib and interconnect with each other to form a network or mesh pattern — like a fishing net or a spider\'s web. This is typical of dicotyledonous plants like peepal, mango, and rose.', sectionId: 5 },
    { id: 15, type: 'sentence', marks: 2, question: 'Use the words "petiole" and "midrib" in a sentence explaining the structure of a leaf.', answer: 'The leaf is attached to the stem by a stalk called the petiole, which continues into the leaf as the midrib — the central thick vein that runs from the base to the apex of the lamina and branches into a network of smaller veins carrying water and minerals throughout the leaf.', hint: 'Petiole = stalk that attaches leaf to stem. Midrib = continuation of petiole into the lamina; central thick vein that branches into smaller veins.', reexplanation: 'The petiole is the stalk-like part that connects the leaf to the stem at the node. The midrib is the main central vein of the leaf — it is the continuation of the petiole into the lamina. From the midrib, smaller veins branch out to carry water and minerals to all parts of the leaf and to collect the food made by photosynthesis.', sectionId: 5 },
    { id: 16, type: 'long_answer', marks: 5, question: 'Name and describe all five modifications of leaves, naming the plant and the purpose of each modification.', answer: '1. Leaf tendril — In pea plants, the leaf is modified into a thin, wire-like, coiled structure called a tendril. The tendril wraps around a support to help the plant climb upward toward sunlight.\n2. Leaf spines — In prickly pear (opuntia), leaves are modified into sharp spines. The spines reduce water loss (important in dry environments) and provide protection from animals.\n3. Scale leaves — In onion, the leaves are modified into thick, fleshy, overlapping scale leaves that store food (in the form of starch) and also protect the buds of the plant.\n4. Reproductive buds — In Bryophyllum and Begonia, the leaves have buds along their margins or surfaces. These buds can produce new plants — a form of vegetative reproduction.\n5. Insectivorous leaf modifications — In plants like pitcher plant (Nepenthes) and Venus fly trap, the leaf is modified to trap and digest insects. In pitcher plant, the lamina becomes a pitcher with a lid, and the petiole becomes a coiled support. In Venus fly trap, the leaf blade is divided into two hinged lobes that close and interlock to trap insects. These modifications help the plant get nitrogen from insects since the soil they grow in lacks nitrogen.', hint: 'List all 5: (1) Tendril — pea plant, climbing; (2) Spines — prickly pear, reduce water loss + protection; (3) Scale leaves — onion, store food + protect buds; (4) Reproduction — Bryophyllum/Begonia, vegetative reproduction; (5) Insectivorous — pitcher plant/Venus fly trap, trap insects for nitrogen.', reexplanation: 'All 5 modifications: Tendril (pea — climbing); Spines (opuntia/prickly pear — water conservation + protection); Scale leaves (onion — food storage + bud protection); Reproduction buds (Bryophyllum/Begonia — vegetative reproduction); Insectivorous (pitcher plant/Venus fly trap — trapping insects for nitrogen in nitrogen-poor soils).', sectionId: 7 },
  ],
}

const q9: ChapterQuiz = {
  chapterId: 9, title: 'Human Body: Respiratory System', totalMarks: 25,
  questions: [
    { id: 1, type: 'mcq', marks: 1, question: 'What is respiration (in the scientific sense)?', options: [{ label: 'A', text: 'Breathing in oxygen through the nose' }, { label: 'B', text: 'The process in which food combines with oxygen inside cells to release energy' }, { label: 'C', text: 'Breathing out carbon dioxide through the lungs' }, { label: 'D', text: 'The exchange of gases in the lungs' }], answer: 'B', reexplanation: 'Respiration is the cellular process in which food (glucose) combines with oxygen inside the cells to release energy. It occurs inside the cells. This is different from breathing, which is the physical process of taking in oxygen-rich air and giving out CO₂-rich air, and occurs outside the cells (in the lungs).' },
    { id: 2, type: 'mcq', marks: 1, question: 'What is the function of the larynx?', options: [{ label: 'A', text: 'Filters air entering the lungs' }, { label: 'B', text: 'Divides into two bronchi' }, { label: 'C', text: 'Contains vocal cords that produce sound' }, { label: 'D', text: 'Controls the rate of breathing' }], answer: 'C', reexplanation: 'The larynx contains vocal cords that help produce sounds — it is the voice box. It is located between the pharynx and the trachea. When air passes over the vocal cords, they vibrate to produce the sounds of speech and singing. The pharynx is the common passage for food and air; the trachea divides into bronchi; and the nose filters air.' },
    { id: 3, type: 'mcq', marks: 1, question: 'What happens to the diaphragm during inhalation?', options: [{ label: 'A', text: 'It relaxes and moves upward' }, { label: 'B', text: 'It stays flat' }, { label: 'C', text: 'It contracts and moves downward' }, { label: 'D', text: 'It pushes air out of the lungs' }], answer: 'C', reexplanation: 'During inhalation (breathing in), the diaphragm contracts and moves downward (flattens). This increases the volume of the thoracic (chest) cavity. As the volume increases, the pressure inside the lungs drops, and air rushes into the lungs through the nose. During exhalation, the diaphragm relaxes and moves upward (dome shape), decreasing chest volume and forcing air out.' },
    { id: 4, type: 'mcq', marks: 1, question: 'Which disease involves the narrowing of bronchi and bronchioles with excessive mucus production?', options: [{ label: 'A', text: 'Pneumonia' }, { label: 'B', text: 'Tuberculosis' }, { label: 'C', text: 'Asthma' }, { label: 'D', text: 'Bronchitis' }], answer: 'C', reexplanation: 'Asthma involves narrowing of the air passage of bronchi and bronchioles. The mucus membrane gets irritated and secretes excessive mucus, clogging the airways. The person has difficulty in breathing along with coughing. Pneumonia is bacterial infection of the lungs; Tuberculosis is a bacterial infection destroying lung tissue; Bronchitis is swelling of the bronchi.' },
    { id: 5, type: 'mcq', marks: 1, question: 'Why is it better to breathe through the nose than through the mouth?', options: [{ label: 'A', text: 'The nose produces more oxygen' }, { label: 'B', text: 'Nose hair and mucus filter, warm, and moisten the air' }, { label: 'C', text: 'The nose is closer to the lungs' }, { label: 'D', text: 'The mouth produces carbon dioxide' }], answer: 'B', reexplanation: 'Breathing through the nose is better because: the nose has thin hair that filters out dust and large particles; the inner lining produces mucus which traps dust particles and germs; the air is warmed and moistened in the nasal cavity before reaching the delicate lung tissue. Mouth breathing bypasses all these protective mechanisms.' },
    { id: 6, type: 'single_word', marks: 1, question: 'Name all six organs of the respiratory system in the correct order.', answer: 'Nose → Pharynx → Larynx → Trachea → Bronchi → Lungs', reexplanation: 'The human respiratory system organs in order: (1) Nose — air entry, filtering, warming; (2) Pharynx — funnel-shaped common passage for food and air; (3) Larynx — voice box with vocal cords; (4) Trachea (windpipe) — long muscular tube; (5) Bronchi — two branches (right and left) entering the lungs; (6) Lungs — site of gas exchange between air and blood.', sectionId: 4 },
    { id: 7, type: 'single_word', marks: 1, question: 'What is mucus and what does it do in the nose?', answer: 'Mucus is a sticky liquid produced by the inner lining of the nose that traps dust particles and germs to prevent them from entering the respiratory system', reexplanation: 'Mucus is a sticky, viscous liquid secreted by goblet cells in the mucous membranes lining the nasal cavity, trachea, and bronchi. In the nose, mucus works together with nasal hair to filter out dust, pollen, bacteria, and other particles. This prevents these potentially harmful substances from reaching the lungs.', sectionId: 4 },
    { id: 8, type: 'single_word', marks: 1, question: 'Name the dome-shaped muscular partition that powers breathing.', answer: 'Diaphragm', reexplanation: 'The diaphragm is a dome-shaped sheet of muscle that forms the floor of the chest cavity. It is the primary muscle of breathing. When it contracts (flattens), it increases the volume of the chest cavity, causing air to rush in (inhalation). When it relaxes (returns to dome shape), it decreases chest volume, forcing air out (exhalation).', sectionId: 4 },
    { id: 9, type: 'single_word', marks: 1, question: 'Name the four common respiratory diseases mentioned in the chapter.', answer: 'Asthma, Bronchitis, Pneumonia, Tuberculosis (TB)', reexplanation: 'Four common respiratory diseases: (1) Asthma — narrowing of bronchi + excess mucus + difficulty breathing; (2) Bronchitis — swelling of bronchi, coughing, can be from allergy/smoking/pollution; (3) Pneumonia — bacterial infection of lungs; (4) Tuberculosis (TB) — bacterial infection that destroys lung tissue. All four affect the respiratory system\'s ability to provide oxygen to the body.', sectionId: 4 },
    { id: 10, type: 'single_word', marks: 1, question: 'Describe what happens during exhalation (breathing out) — what does the diaphragm do?', answer: 'During exhalation: diaphragm relaxes and moves upward (dome shape) → ribs move inward and downward → chest volume decreases → pressure increases → air is forced out', reexplanation: 'Exhalation (breathing out) is the opposite of inhalation: (1) Diaphragm relaxes and moves upward back into its dome shape; (2) Muscles of the rib cage relax, ribs move inward and downward; (3) Volume of the thoracic cavity decreases; (4) Pressure inside the lungs increases; (5) Air is forced out of the lungs through the bronchi, trachea, larynx, pharynx, and nose.', sectionId: 4 },
    { id: 11, type: 'sentence', marks: 2, question: 'Use the words "trachea" and "bronchi" in a sentence explaining how air reaches the lungs.', answer: 'After passing through the nose, pharynx, and larynx, air enters the trachea (windpipe) — a long muscular tube — which then divides into two bronchi, the right bronchus entering the right lung and the left bronchus entering the left lung.', hint: 'Trachea = windpipe; runs in front of food pipe; divides into two bronchi. Bronchi = right and left bronchus; each enters one lung.', reexplanation: 'Air travel path: Nose → Pharynx → Larynx → Trachea → (divides into) Right bronchus + Left bronchus → respective lungs. The trachea is a delicate, muscular tube kept open by rings of cartilage. The two bronchi further divide into smaller bronchioles inside the lungs, eventually ending in tiny air sacs called alveoli where gas exchange occurs.', sectionId: 5 },
    { id: 12, type: 'sentence', marks: 2, question: 'Use the word "inhalation" in a sentence listing 4 things that happen when you breathe in.', answer: 'During inhalation, four things happen simultaneously: the diaphragm contracts and moves down, the muscles of the rib cage contract lifting the ribs upward and outward, the volume of the thoracic cavity increases, and the pressure inside the lungs drops — causing air to rush into the lungs through the nose.', hint: 'Inhalation: (1) diaphragm contracts/moves down, (2) ribs move up and out, (3) chest volume increases, (4) pressure drops → air rushes in.', reexplanation: 'Inhalation is an active process requiring muscle contraction. The diaphragm (primary muscle) contracts and flattens. Intercostal muscles between ribs also contract, lifting the ribs up and outward. These combined actions increase the volume of the chest cavity. As volume increases, pressure drops (Boyle\'s Law), and atmospheric air rushes into the lungs.', sectionId: 5 },
    { id: 13, type: 'sentence', marks: 2, question: 'Use the word "Pranayam" in a sentence about respiratory health.', answer: 'Pranayam — traditional yogic breathing exercises — can significantly improve the efficiency and capacity of the lungs by strengthening the diaphragm and respiratory muscles, training the body to use oxygen more effectively, and reducing stress on the respiratory system.', hint: 'Pranayam = yogic breathing exercises. Benefits: improve lung efficiency, strengthen breathing muscles, improve oxygen use.', reexplanation: 'Pranayam is an ancient Indian system of conscious breathing control. Modern research confirms that regular pranayam practice can: increase lung capacity, strengthen the diaphragm, improve oxygen exchange, reduce stress hormones, and help manage conditions like asthma. It is the only form of exercise that specifically trains the respiratory muscles.', sectionId: 5 },
    { id: 14, type: 'sentence', marks: 2, question: 'Use the word "bronchitis" in a sentence explaining its causes and effect on breathing.', answer: 'Bronchitis is a respiratory disease caused by swelling of the bronchi — it can result from allergies, cigarette smoking, air pollution, or lack of immunity — and leads to persistent coughing because the swollen bronchi narrow the air passages.', hint: 'Bronchitis: swelling of bronchi → coughing; causes: allergy, cigarette smoking, air pollution, lack of immunity, hereditary.', reexplanation: 'Bronchitis is inflammation (swelling) of the bronchi — the airways leading to the lungs. When the bronchi swell, the air passage narrows, making breathing difficult and triggering coughing. It can be caused by respiratory infections, cigarette smoke, air pollution, allergens, or inherited immune deficiencies.', sectionId: 5 },
    { id: 15, type: 'sentence', marks: 2, question: 'Use the word "pharynx" in a sentence explaining why food and air share the same passage.', answer: 'The pharynx is the common passage for both food and air — food from the mouth and air from the nose both pass through the funnel-shaped pharynx before separating, food going to the oesophagus (food pipe) and air going to the larynx and then the trachea.', hint: 'Pharynx: funnel-shaped, common passage for food (from mouth) and air (from nose). After pharynx: food → oesophagus/food pipe, air → larynx → trachea.', reexplanation: 'The pharynx serves as the junction between the digestive and respiratory systems. It is the shared passage where food and air meet briefly. From the pharynx, air goes toward the larynx and then the trachea (respiratory route), while food is directed to the oesophagus (digestive route). A small flap called the epiglottis normally prevents food from going down the airway.', sectionId: 5 },
    { id: 16, type: 'long_answer', marks: 5, question: 'Describe the complete mechanism of breathing — explain both inhalation and exhalation, including the role of the diaphragm, ribs, and chest cavity in each.', answer: 'Breathing consists of two phases: inhalation and exhalation.\n\nInhalation (Breathing in / Inspiration):\nThe diaphragm — the dome-shaped muscular partition below the lungs — contracts and moves downward, flattening itself. Simultaneously, the muscles attached to the rib cage contract, lifting the ribs upward and outward. These two actions increase the volume of the thoracic (chest) cavity. As the volume of the chest cavity increases, the pressure inside the lungs drops below atmospheric pressure. Because gases move from high pressure to low pressure, air rushes into the lungs through the nose, pharynx, larynx, trachea, and bronchi. The lungs expand (stretch) to accommodate the incoming air.\n\nExhalation (Breathing out / Expiration):\nThe diaphragm relaxes and moves upward, returning to its dome shape. The muscles of the rib cage also relax, allowing the ribs to move inward and downward. These actions decrease the volume of the thoracic cavity. As the volume decreases, the pressure inside the lungs increases above atmospheric pressure. The high pressure forces air out of the lungs, through the bronchi, trachea, larynx, pharynx, and out through the nose. The lungs spring back to their normal shape (they are elastic and spongy).\n\nIn summary: Inhalation is an active process (muscles contract), while exhalation is largely passive (muscles relax). The diaphragm is the primary muscle of breathing.', hint: 'Inhalation: diaphragm contracts (moves down) + ribs up and out → chest volume increases → pressure drops → air rushes in. Exhalation: diaphragm relaxes (moves up) + ribs in and down → chest volume decreases → pressure increases → air forced out.', reexplanation: 'Cover both phases completely: Inhalation (active — muscles contract; diaphragm flattens + ribs up/out → chest volume ↑ → pressure ↓ → air IN); Exhalation (passive — muscles relax; diaphragm domes + ribs in/down → chest volume ↓ → pressure ↑ → air OUT). Mention lungs are elastic — expand on inhalation, contract on exhalation.', sectionId: 7 },
  ],
}

export const ALL_SCI_QUIZZES: ChapterQuiz[] = [q1, q2, q3, q4, q5, q6, q7, q8, q9]
export function getSciQuiz(chapterId: number): ChapterQuiz | undefined { return ALL_SCI_QUIZZES.find(q => q.chapterId === chapterId) }
